package solution

import "testing"

func TestQueueOrderingPaginationAndIsolation(t *testing.T) {
	input := []Article{
		{Key: "c", Writer: "wc", Headline: "hc", Link: "lc", Priority: 1},
		{Key: "b", Writer: "wb", Headline: "hb", Link: "lb", Priority: 3},
		{Key: "a", Writer: "wa", Headline: "ha", Link: "la", Priority: 3},
	}
	q, err := NewQueue(input, 2)
	if err != nil { t.Fatalf("NewQueue: %v", err) }

	input[0].Key = "changed"
	input[1].Priority = -100

	req := PageRequest{Account: "acct", Limit: 2, ScanBudget: 2}
	got, err := q.NextPage(req)
	if err != nil { t.Fatalf("NextPage: %v", err) }
	if req != (PageRequest{Account: "acct", Limit: 2, ScanBudget: 2}) { t.Fatalf("request mutated: %+v", req) }
	if len(got.Items) != 2 || got.Items[0].Key != "a" || got.Items[1].Key != "b" { t.Fatalf("unexpected first page: %+v", got.Items) }
	if got.NextCursor != "b" { t.Fatalf("NextCursor = %q", got.NextCursor) }
	if got.Trace != (TraceRecord{Name: "queue.next", Scanned: 2, Returned: 2}) { t.Fatalf("trace = %+v", got.Trace) }

	got.Items[0].Key = "corrupt"
	got.Items[1].Headline = "corrupt"
	again, err := q.NextPage(req)
	if err != nil { t.Fatalf("repeat NextPage: %v", err) }
	if again.Items[0].Key != "a" || again.Items[1].Headline != "hb" { t.Fatalf("result aliases queue or prior result: %+v", again.Items) }

	last, err := q.NextPage(PageRequest{Account: "acct", Cursor: "b", Limit: 2, ScanBudget: 9})
	if err != nil { t.Fatalf("last page: %v", err) }
	if len(last.Items) != 1 || last.Items[0].Key != "c" || last.NextCursor != "" { t.Fatalf("unexpected last page: %+v", last) }
	if last.Trace != (TraceRecord{Name: "queue.next", Scanned: 1, Returned: 1}) { t.Fatalf("last trace = %+v", last.Trace) }

	end, err := q.NextPage(PageRequest{Account: "acct", Cursor: "c", Limit: 1, ScanBudget: 1})
	if err != nil || len(end.Items) != 0 || end.NextCursor != "" { t.Fatalf("end page = %+v, %v", end, err) }
	if end.Trace != (TraceRecord{Name: "queue.next"}) { t.Fatalf("end trace = %+v", end.Trace) }
}

func TestQueueNativeMaxIntLimitsUseTinyStorage(t *testing.T) {
	maxInt := int(^uint(0) >> 1)

	one, err := NewQueue([]Article{{Key: "only"}}, maxInt)
	if err != nil { t.Fatal(err) }
	exhausted, err := one.NextPage(PageRequest{Account: "acct", Cursor: "only", Limit: maxInt, ScanBudget: maxInt})
	if err != nil { t.Fatalf("exhausted page: %v", err) }
	if len(exhausted.Items) != 0 || exhausted.NextCursor != "" || exhausted.Trace != (TraceRecord{Name: "queue.next"}) {
		t.Fatalf("exhausted page=%+v", exhausted)
	}

	two, err := NewQueue([]Article{{Key: "a"}, {Key: "b"}}, maxInt)
	if err != nil { t.Fatal(err) }
	page, err := two.NextPage(PageRequest{Account: "acct", Cursor: "a", Limit: maxInt, ScanBudget: maxInt})
	if err != nil { t.Fatalf("large-limit page: %v", err) }
	if len(page.Items) != 1 || page.Items[0].Key != "b" || page.NextCursor != "" {
		t.Fatalf("large-limit page=%+v", page)
	}
	if page.Trace != (TraceRecord{Name: "queue.next", Scanned: 1, Returned: 1}) { t.Fatalf("trace=%+v", page.Trace) }
}

func TestQueueDeterministicAcrossInputOrders(t *testing.T) {
	a := []Article{{Key: "z", Priority: 2}, {Key: "a", Priority: 2}, {Key: "m", Priority: 4}}
	b := []Article{a[1], a[2], a[0]}
	q1, e1 := NewQueue(a, 3)
	q2, e2 := NewQueue(b, 3)
	if e1 != nil || e2 != nil { t.Fatalf("construction errors: %v, %v", e1, e2) }
	r := PageRequest{Account: "x", Limit: 3, ScanBudget: 3}
	p1, e1 := q1.NextPage(r)
	p2, e2 := q2.NextPage(r)
	if e1 != nil || e2 != nil { t.Fatalf("page errors: %v, %v", e1, e2) }
	for i, key := range []string{"m", "a", "z"} {
		if p1.Items[i].Key != key || p2.Items[i].Key != key { t.Fatalf("order differs: %+v / %+v", p1.Items, p2.Items) }
	}
}

func TestQueueConstructionValidation(t *testing.T) {
	cases := []struct {
		articles []Article
		maxPage int
	}{
		{nil, 0}, {nil, -1},
		{[]Article{{Key: ""}}, 1},
		{[]Article{{Key: "x"}, {Key: "x"}}, 1},
	}
	for i, tc := range cases {
		_, err := NewQueue(tc.articles, tc.maxPage)
		if err != ErrInvalidRequest { t.Errorf("case %d: err=%v", i, err) }
	}
}

func TestQueueRequestErrorsReturnZeroResult(t *testing.T) {
	q, err := NewQueue([]Article{{Key: "a"}, {Key: "b"}}, 2)
	if err != nil { t.Fatal(err) }
	invalid := []PageRequest{
		{Account: "", Limit: 1, ScanBudget: 1},
		{Account: "x", Limit: 0, ScanBudget: 1},
		{Account: "x", Limit: 3, ScanBudget: 3},
	}
	for _, req := range invalid {
		got, err := q.NextPage(req)
		if err != ErrInvalidRequest { t.Errorf("request %+v: %v", req, err) }
		assertZeroPage(t, got)
	}
	got, err := q.NextPage(PageRequest{Account: "x", Limit: 2, ScanBudget: 1})
	if err != ErrBudgetExceeded { t.Fatalf("budget error = %v", err) }
	assertZeroPage(t, got)

	got, err = q.NextPage(PageRequest{Account: "x", Cursor: "missing", Limit: 1, ScanBudget: 1})
	if err != ErrCursorNotFound { t.Fatalf("cursor error = %v", err) }
	assertZeroPage(t, got)

	var nilQ *Queue
	got, err = nilQ.NextPage(PageRequest{Account: "x", Limit: 1, ScanBudget: 1})
	if err != ErrInvalidRequest { t.Fatalf("nil receiver error = %v", err) }
	assertZeroPage(t, got)
}

func TestEmptyQueue(t *testing.T) {
	q, err := NewQueue(nil, 1)
	if err != nil { t.Fatal(err) }
	got, err := q.NextPage(PageRequest{Account: "x", Limit: 1, ScanBudget: 1})
	if err != nil { t.Fatal(err) }
	if len(got.Items) != 0 { t.Fatalf("Items must be empty: %#v", got.Items) }
	if got.NextCursor != "" || got.Trace != (TraceRecord{Name: "queue.next"}) { t.Fatalf("result = %+v", got) }
}

func assertZeroPage(t *testing.T, got PageResult) {
	t.Helper()
	if got.Items != nil || got.NextCursor != "" || got.Trace != (TraceRecord{}) { t.Fatalf("non-zero error result: %+v", got) }
}

