package solution

import "testing"

func TestScratchValidationAndZeroSize(t *testing.T) {
	for _, tc := range [][2]int{{-1, 0}, {1, -1}, {1, 2}} {
		_, err := NewScratch(tc[0], tc[1])
		if err != ErrInvalidCapacity { t.Errorf("NewScratch(%d,%d) error = %v", tc[0], tc[1], err) }
	}
	s, err := NewScratch(0, 0)
	if err != nil { t.Fatal(err) }
	b, err := s.Take(0)
	if err != nil || b == nil || len(b) != 0 || s.Used() != 0 { t.Fatalf("zero Take = %#v, %v, used %d", b, err, s.Used()) }
	_, err = s.Take(-1)
	if err != ErrInvalidSize || s.Used() != 0 { t.Fatalf("negative Take error = %v, used %d", err, s.Used()) }
}

func TestScratchSharedExactFitDisjointAndReset(t *testing.T) {
	s, err := NewScratch(5, 3)
	if err != nil { t.Fatal(err) }
	a, err := s.Take(2)
	if err != nil { t.Fatal(err) }
	b, err := s.Take(3)
	if err != nil { t.Fatal(err) }
	if s.Used() != 5 { t.Fatalf("Used = %d", s.Used()) }
	for _, x := range append(append([]byte{}, a...), b...) {
		if x != 0 { t.Fatal("allocation was not zeroed") }
	}
	a[0], a[1] = 7, 8
	b[0] = 9
	if b[0] != 9 || a[0] != 7 { t.Fatal("shared regions unexpectedly overlap") }

	s.Reset()
	if s.Used() != 0 { t.Fatalf("Used after reset = %d", s.Used()) }
	reused, err := s.Take(3)
	if err != nil { t.Fatal(err) }
	for i, x := range reused {
		if x != 0 { t.Fatalf("reused[%d] = %d", i, x) }
	}
	s.Reset()
	s.Reset()
	if s.Used() != 0 { t.Fatalf("Used after repeated reset = %d", s.Used()) }
}

func TestScratchAppendCannotContaminateFutureOrAdjacentRegions(t *testing.T) {
	s, err := NewScratch(4, 4)
	if err != nil { t.Fatal(err) }
	first, err := s.Take(1)
	if err != nil { t.Fatal(err) }
	first = append(first, 7)
	second, err := s.Take(1)
	if err != nil { t.Fatal(err) }
	if second[0] != 0 { t.Fatalf("future allocation was contaminated: %v", second) }

	adjacent, err := NewScratch(4, 4)
	if err != nil { t.Fatal(err) }
	left, _ := adjacent.Take(1)
	right, _ := adjacent.Take(1)
	right[0] = 5
	left = append(left, 9)
	if right[0] != 5 { t.Fatalf("append through earlier allocation changed adjacent live region: %v", right) }
}

func TestScratchFallbackDoesNotConsumeOrAlias(t *testing.T) {
	s, err := NewScratch(4, 2)
	if err != nil { t.Fatal(err) }
	shared, _ := s.Take(2)
	shared[0] = 4

	tooLarge, err := s.Take(3)
	if err != nil { t.Fatal(err) }
	if s.Used() != 2 { t.Fatalf("large fallback changed Used: %d", s.Used()) }
	exact, err := s.Take(2)
	if err != nil { t.Fatal(err) }
	if s.Used() != 4 { t.Fatalf("exact remaining fit was not shared: %d", s.Used()) }
	overflow, err := s.Take(1)
	if err != nil || s.Used() != 4 { t.Fatalf("overflow fallback: %v used=%d", err, s.Used()) }

	for _, b := range [][]byte{tooLarge, exact, overflow} {
		for _, x := range b {
			if x != 0 { t.Fatal("returned byte not initially zero") }
		}
	}
	tooLarge[0] = 11
	overflow[0] = 12
	if shared[0] != 4 || exact[0] != 0 || tooLarge[0] != 11 || overflow[0] != 12 { t.Fatal("allocations alias unexpectedly") }

	x, _ := s.Take(3)
	y, _ := s.Take(3)
	x[0] = 99
	if y[0] != 0 { t.Fatal("independent fallbacks alias one another") }
}

