Implement a pure reconciliation function in package solution using only the standard library.

Export:
- type Condition struct { Type string; Active bool }
- type Blueprint struct { Name string; Labels map[string]string }
- type Workload struct { Name string; Labels map[string]string; Conditions []Condition }
- type Result struct { Action string; Workload *Workload; Conditions []Condition }
- func Reconcile(blueprint Blueprint, current *Workload) (Result, error)

An empty blueprint Name or any empty label key is malformed and returns action "error", an active condition of type "Invalid", and a non-nil error. If current is nil, return action "create", a new workload matching the blueprint, and active condition "Provisioning". If current has label lifecycle=remove, return action "delete", nil Workload, and active condition "Removing". Otherwise, if its name or labels differ exactly from the blueprint, return action "update" with a matching workload and active condition "Synchronizing". If already equal, return action "none", a copy of current, and a copy of its existing conditions. Nil and empty label maps compare equal. Never mutate or alias maps or condition slices supplied by the caller.

Return only the complete source file; do not include Markdown fences or prose.

package solution

import "errors"

type Condition struct {
	Type   string
	Active bool
}

type Blueprint struct {
	Name   string
	Labels map[string]string
}

type Workload struct {
	Name       string
	Labels     map[string]string
	Conditions []Condition
}

type Result struct {
	Action     string
	Workload   *Workload
	Conditions []Condition
}

func labelsCopy(labels map[string]string) map[string]string {
	if labels == nil {
		return nil
	}
	copied := make(map[string]string, len(labels))
	for key, value := range labels {
		copied[key] = value
	}
	return copied
}

func labelsEqual(a, b map[string]string) bool {
	if len(a) != len(b) {
		return false
	}
	for key, value := range a {
		other, exists := b[key]
		if !exists || other != value {
			return false
		}
	}
	return true
}

func workloadCopy(workload *Workload) *Workload {
	if workload == nil {
		return nil
	}
	return &Workload{
		Name:       workload.Name,
		Labels:     labelsCopy(workload.Labels),
		Conditions: append([]Condition(nil), workload.Conditions...),
	}
}

func Reconcile(blueprint Blueprint, current *Workload) (Result, error) {
	if blueprint.Name == "" {
		conditions := []Condition{{Type: "Invalid", Active: true}}
		return Result{Action: "error", Conditions: conditions}, errors.New("empty name")
	}
	for key := range blueprint.Labels {
		if key == "" {
			conditions := []Condition{{Type: "Invalid", Active: true}}
			return Result{Action: "error", Conditions: conditions}, errors.New("empty label key")
		}
	}
	if current == nil {
		conditions := []Condition{{Type: "Provisioning", Active: true}}
		workload := &Workload{
			Name:       blueprint.Name,
			Labels:     labelsCopy(blueprint.Labels),
			Conditions: append([]Condition(nil), conditions...),
		}
		return Result{Action: "create", Workload: workload, Conditions: conditions}, nil
	}
	if current.Labels["lifecycle"] == "remove" {
		conditions := []Condition{{Type: "Removing", Active: true}}
		return Result{Action: "delete", Conditions: conditions}, nil
	}
	if current.Name != blueprint.Name || !labelsEqual(current.Labels, blueprint.Labels) {
		conditions := []Condition{{Type: "Synchronizing", Active: true}}
		workload := &Workload{
			Name:       blueprint.Name,
			Labels:     labelsCopy(blueprint.Labels),
			Conditions: append([]Condition(nil), conditions...),
		}
		return Result{Action: "update", Workload: workload, Conditions: conditions}, nil
	}
	workload := workloadCopy(current)
	conditions := append([]Condition(nil), current.Conditions...)
	return Result{Action: "none", Workload: workload, Conditions: conditions}, nil
}

