package solution

import (
	"reflect"
	"testing"
)

func TestReconcileMalformedBlueprint(t *testing.T) {
	cases := []Blueprint{
		{Name: "", Labels: map[string]string{"x": "y"}},
		{Name: "ok", Labels: map[string]string{"": "value"}},
	}
	for _, bp := range cases {
		res, err := Reconcile(bp, nil)
		if err == nil || res.Action != "error" { t.Fatalf("result=%+v err=%v", res, err) }
		if len(res.Conditions) != 1 || res.Conditions[0] != (Condition{Type: "Invalid", Active: true}) { t.Fatalf("conditions=%+v", res.Conditions) }
	}
}

func TestReconcileCreateCopiesBlueprint(t *testing.T) {
	bp := Blueprint{Name: "app", Labels: map[string]string{"tier": "api"}}
	res, err := Reconcile(bp, nil)
	if err != nil { t.Fatal(err) }
	if res.Action != "create" || res.Workload == nil || res.Workload.Name != "app" || !reflect.DeepEqual(res.Workload.Labels, bp.Labels) { t.Fatalf("result=%+v", res) }
	if len(res.Conditions) != 1 || res.Conditions[0] != (Condition{Type: "Provisioning", Active: true}) { t.Fatalf("conditions=%+v", res.Conditions) }
	res.Workload.Labels["tier"] = "changed"
	if bp.Labels["tier"] != "api" { t.Fatal("result aliases blueprint labels") }
}

func TestReconcileDeleteTakesPrecedenceAndDoesNotAlias(t *testing.T) {
	current := &Workload{Name: "different", Labels: map[string]string{"lifecycle": "remove", "x": "y"}, Conditions: []Condition{{Type: "Old", Active: true}}}
	before := cloneWorkload(current)
	res, err := Reconcile(Blueprint{Name: "wanted", Labels: map[string]string{"x": "z"}}, current)
	if err != nil { t.Fatal(err) }
	if res.Action != "delete" || res.Workload != nil || len(res.Conditions) != 1 || res.Conditions[0] != (Condition{Type: "Removing", Active: true}) { t.Fatalf("result=%+v", res) }
	if !reflect.DeepEqual(current, before) { t.Fatal("current was mutated") }
}

func TestReconcileUpdateForNameOrLabels(t *testing.T) {
	cases := []*Workload{
		{Name: "old", Labels: map[string]string{"a": "b"}},
		{Name: "new", Labels: map[string]string{"a": "different"}},
		{Name: "new", Labels: map[string]string{"a": "b", "extra": "x"}},
		{Name: "new", Labels: map[string]string{"existing": ""}},
	}
	for _, current := range cases {
		bp := Blueprint{Name: "new", Labels: map[string]string{"a": "b"}}
		if current.Labels["existing"] == "" && len(current.Labels) == 1 {
			bp.Labels = map[string]string{"desired": ""}
		}
		res, err := Reconcile(bp, current)
		if err != nil { t.Fatal(err) }
		if res.Action != "update" || res.Workload == nil || res.Workload.Name != bp.Name || !reflect.DeepEqual(res.Workload.Labels, bp.Labels) { t.Fatalf("result=%+v", res) }
		if len(res.Conditions) != 1 || res.Conditions[0] != (Condition{Type: "Synchronizing", Active: true}) { t.Fatalf("conditions=%+v", res.Conditions) }
		for k := range res.Workload.Labels { res.Workload.Labels[k] = "mutated" }
		if reflect.DeepEqual(res.Workload.Labels, bp.Labels) || reflect.DeepEqual(res.Workload.Labels, current.Labels) { t.Fatal("update result aliases input") }
	}
}

func TestReconcileEmptyValueKeysComparedExactly(t *testing.T) {
	current := &Workload{Name: "same", Labels: map[string]string{"existing": ""}}
	res, err := Reconcile(Blueprint{Name: "same", Labels: map[string]string{"desired": ""}}, current)
	if err != nil || res.Action != "update" { t.Fatalf("different empty-valued keys: result=%+v err=%v", res, err) }
	if !reflect.DeepEqual(res.Workload.Labels, map[string]string{"desired": ""}) { t.Fatalf("updated labels=%v", res.Workload.Labels) }

	matching := &Workload{Name: "same", Labels: map[string]string{"desired": ""}, Conditions: []Condition{{Type: "Ready", Active: true}}}
	res, err = Reconcile(Blueprint{Name: "same", Labels: map[string]string{"desired": ""}}, matching)
	if err != nil || res.Action != "none" { t.Fatalf("matching empty-valued key: result=%+v err=%v", res, err) }
	res.Workload.Labels["desired"] = "changed"
	if matching.Labels["desired"] != "" { t.Fatal("none result aliases current labels") }
}

func TestReconcileNoneTreatsNilAndEmptyLabelsEqualAndCopies(t *testing.T) {
	current := &Workload{Name: "same", Labels: nil, Conditions: []Condition{{Type: "Ready", Active: true}}}
	res, err := Reconcile(Blueprint{Name: "same", Labels: map[string]string{}}, current)
	if err != nil { t.Fatal(err) }
	if res.Action != "none" || res.Workload == nil || res.Workload == current { t.Fatalf("result=%+v", res) }
	if !reflect.DeepEqual(res.Conditions, current.Conditions) || !reflect.DeepEqual(res.Workload.Conditions, current.Conditions) { t.Fatalf("conditions not copied: %+v", res) }
	res.Conditions[0].Type = "changed"
	res.Workload.Conditions[0].Active = false
	if current.Conditions[0] != (Condition{Type: "Ready", Active: true}) { t.Fatal("condition slices alias current") }
}

func TestReconcileMalformedDoesNotMutateInputs(t *testing.T) {
	bp := Blueprint{Name: "ok", Labels: map[string]string{"": "x"}}
	cur := &Workload{Name: "c", Labels: map[string]string{"a": "b"}, Conditions: []Condition{{Type: "C", Active: true}}}
	beforeBP := cloneLabels(bp.Labels)
	before := cloneWorkload(cur)
	_, err := Reconcile(bp, cur)
	if err == nil { t.Fatal("expected non-nil error") }
	if !reflect.DeepEqual(cur, before) || !reflect.DeepEqual(bp.Labels, beforeBP) { t.Fatal("input mutated on error") }
}

func cloneWorkload(w *Workload) *Workload {
	c := &Workload{Name: w.Name, Labels: cloneLabels(w.Labels), Conditions: append([]Condition(nil), w.Conditions...)}
	return c
}

func cloneLabels(in map[string]string) map[string]string {
	if in == nil { return nil }
	out := make(map[string]string, len(in))
	for k, v := range in { out[k] = v }
	return out
}

