package solution

import (
	"reflect"
	"strconv"
	"strings"
	"testing"
	"unsafe"
)

type methodFixture struct{ Count int }

func (m methodFixture) Add(a int, b int) int { return a + b }
func (m methodFixture) AcceptAny(v any) any { return v }
func (m methodFixture) Pair(s string) (string, int) { return s, len(s) }
func (m methodFixture) NoResults() {}
func (m methodFixture) Variadic(base int, parts ...string) string {
	return strconv.Itoa(base) + ":" + strings.Join(parts, ",")
}
func (m methodFixture) IsNilPointer(p unsafe.Pointer) bool { return p == nil }
func (m *methodFixture) Bump(n int) { m.Count += n }
func (m *methodFixture) PanicAfterBump() { m.Count++; panic("boom") }
func (m methodFixture) hidden() {}

type noMethods struct{}

func TestListCallableValueAndPointer(t *testing.T) {
	list, err := ListCallable(methodFixture{})
	if err != nil { t.Fatal(err) }
	wantNames := []string{"AcceptAny", "Add", "IsNilPointer", "NoResults", "Pair", "Variadic"}
	if len(list) != len(wantNames) { t.Fatalf("methods=%+v", list) }
	for i, name := range wantNames {
		if list[i].Name != name { t.Fatalf("methods not sorted/exported only: %+v", list) }
	}
	add := list[1]
	if !reflect.DeepEqual(add.Inputs, []reflect.Type{reflect.TypeOf(int(0)), reflect.TypeOf(int(0))}) || !reflect.DeepEqual(add.Outputs, []reflect.Type{reflect.TypeOf(int(0))}) { t.Fatalf("Add signature=%+v", add) }
	pair := list[4]
	if !reflect.DeepEqual(pair.Inputs, []reflect.Type{reflect.TypeOf("")}) || !reflect.DeepEqual(pair.Outputs, []reflect.Type{reflect.TypeOf(""), reflect.TypeOf(int(0))}) { t.Fatalf("Pair signature=%+v", pair) }
	variadic := list[5]
	if !reflect.DeepEqual(variadic.Inputs, []reflect.Type{reflect.TypeOf(int(0)), reflect.TypeOf([]string(nil))}) { t.Fatalf("Variadic signature=%+v", variadic) }

	m := &methodFixture{Count: 2}
	ptrList, err := ListCallable(m)
	if err != nil { t.Fatal(err) }
	if m.Count != 2 { t.Fatal("listing invoked or mutated receiver") }
	foundBump := false
	for _, sig := range ptrList {
		if sig.Name == "Bump" { foundBump = true }
	}
	if !foundBump { t.Fatalf("pointer method absent: %+v", ptrList) }
}

func TestListCallableEmptyAndNil(t *testing.T) {
	got, err := ListCallable(noMethods{})
	if err != nil || got == nil || len(got) != 0 { t.Fatalf("empty list=%#v err=%v", got, err) }
	if _, err = ListCallable(nil); err == nil { t.Fatal("nil receiver accepted") }
	var p *methodFixture
	if _, err = ListCallable(p); err == nil { t.Fatal("typed nil receiver accepted") }
}

func TestInvokeResultsMutationAndExactTypes(t *testing.T) {
	m := &methodFixture{}
	args := []any{2}
	results, err := Invoke(m, "Bump", args)
	if err != nil || results == nil || len(results) != 0 || m.Count != 2 { t.Fatalf("Bump results=%#v err=%v count=%d", results, err, m.Count) }
	if len(args) != 1 || args[0] != 2 { t.Fatalf("args mutated: %#v", args) }

	results, err = Invoke(*m, "Pair", []any{"abc"})
	if err != nil || len(results) != 2 || results[0] != "abc" || results[1] != 3 { t.Fatalf("Pair=%#v err=%v", results, err) }

	type namedInt int
	if _, err = Invoke(*m, "Add", []any{namedInt(1), 2}); err == nil { t.Fatal("convertible argument accepted") }
	if _, err = Invoke(*m, "Add", []any{1}); err == nil { t.Fatal("wrong arity accepted") }
}

func TestInvokeVariadicUsesDeclaredSliceArgument(t *testing.T) {
	m := methodFixture{}
	args := []any{2, []string{"a", "b"}}
	results, err := Invoke(m, "Variadic", args)
	if err != nil || !reflect.DeepEqual(results, []any{"2:a,b"}) { t.Fatalf("Variadic=%#v err=%v", results, err) }
	if !reflect.DeepEqual(args, []any{2, []string{"a", "b"}}) { t.Fatalf("args mutated: %#v", args) }

	var nilParts []string
	results, err = Invoke(m, "Variadic", []any{3, nilParts})
	if err != nil || !reflect.DeepEqual(results, []any{"3:"}) { t.Fatalf("typed nil slice=%#v err=%v", results, err) }
	results, err = Invoke(m, "Variadic", []any{4, nil})
	if err != nil || !reflect.DeepEqual(results, []any{"4:"}) { t.Fatalf("untyped nil slice=%#v err=%v", results, err) }

	if _, err = Invoke(m, "Variadic", []any{2, "a", "b"}); err == nil { t.Fatal("expanded variadic arguments accepted") }
	if _, err = Invoke(m, "Variadic", []any{2, "a"}); err == nil { t.Fatal("scalar accepted for declared variadic slice") }
}

func TestInvokeNilArguments(t *testing.T) {
	m := methodFixture{}
	results, err := Invoke(m, "AcceptAny", []any{nil})
	if err != nil || len(results) != 1 || results[0] != nil { t.Fatalf("nil interface argument: %#v %v", results, err) }
	results, err = Invoke(m, "IsNilPointer", []any{nil})
	if err != nil || !reflect.DeepEqual(results, []any{true}) { t.Fatalf("nil unsafe pointer: %#v %v", results, err) }
	if _, err = Invoke(m, "Add", []any{nil, 1}); err == nil { t.Fatal("nil accepted for int") }
}

func TestInvokeRejectsBadReceiverOrName(t *testing.T) {
	var typedNil *methodFixture
	cases := []struct{ receiver any; name string }{
		{nil, "Add"}, {typedNil, "Bump"}, {methodFixture{}, ""},
		{methodFixture{}, "add"}, {methodFixture{}, "Missing"}, {methodFixture{}, "hidden"},
	}
	for _, tc := range cases {
		if _, err := Invoke(tc.receiver, tc.name, nil); err == nil { t.Errorf("Invoke(%T,%q) accepted", tc.receiver, tc.name) }
	}
}

func TestInvokeRecoversPanicAndPreservesPriorMutation(t *testing.T) {
	m := &methodFixture{}
	results, err := Invoke(m, "PanicAfterBump", nil)
	if err == nil || results != nil { t.Fatalf("panic result=%#v err=%v", results, err) }
	if m.Count != 1 { t.Fatalf("mutation before panic lost: %d", m.Count) }
}

