package solution

import (
	"fmt"
	"reflect"
	"sort"
	"sync"
	"testing"
)

type registryValue struct {
	Name string         `json:"name"`
	Tags []string       `json:"tags"`
	Meta map[string]int `json:"meta"`
}

func TestRegistryPutGetReplacementAndIsolation(t *testing.T) {
	r := NewRegistry()
	if r == nil { t.Fatal("NewRegistry returned nil") }
	in := registryValue{Name: "first", Tags: []string{"a"}, Meta: map[string]int{"x": 1}}
	if err := r.Put("k", in); err != nil { t.Fatal(err) }
	in.Tags[0] = "changed"
	in.Meta["x"] = 99

	var got registryValue
	found, err := r.Get("k", &got)
	if err != nil || !found { t.Fatalf("Get: found=%v err=%v", found, err) }
	if got.Name != "first" || !reflect.DeepEqual(got.Tags, []string{"a"}) || !reflect.DeepEqual(got.Meta, map[string]int{"x": 1}) { t.Fatalf("got=%+v", got) }
	got.Tags[0] = "mutated"
	got.Meta["x"] = 8
	var again registryValue
	found, err = r.Get("k", &again)
	if err != nil || !found || again.Tags[0] != "a" || again.Meta["x"] != 1 { t.Fatalf("Get aliases internal data: %+v, %v", again, err) }

	if err := r.Put("k", registryValue{Name: "second"}); err != nil { t.Fatal(err) }
	var replaced registryValue
	found, err = r.Get("k", &replaced)
	if err != nil || !found || replaced.Name != "second" { t.Fatalf("replacement=%+v found=%v err=%v", replaced, found, err) }
}

func TestRegistryInvalidOperationsAndAtomicEncodingFailure(t *testing.T) {
	r := NewRegistry()
	if err := r.Put("", 1); err == nil { t.Fatal("empty Put key accepted") }
	if err := r.Put("stable", map[string]int{"v": 1}); err != nil { t.Fatal(err) }
	if err := r.Put("stable", make(chan int)); err == nil { t.Fatal("unencodable value accepted") }
	var stable map[string]int
	found, err := r.Get("stable", &stable)
	if err != nil || !found || stable["v"] != 1 { t.Fatalf("failed Put changed registry: %#v %v", stable, err) }

	for _, dst := range []any{nil, 1, map[string]int(nil), (*int)(nil)} {
		if _, err = r.Get("stable", dst); err == nil { t.Errorf("invalid present destination accepted: %#v", dst) }
		if _, err = r.Get("absent", dst); err == nil { t.Errorf("invalid absent destination accepted: %#v", dst) }
	}
	var x int
	if _, err = r.Get("", &x); err == nil { t.Fatal("empty Get key accepted") }

	x = 17
	found, err = r.Get("absent", &x)
	if err != nil || found || x != 17 { t.Fatalf("absent Get mutated dst: found=%v err=%v x=%d", found, err, x) }

	var incompatible int
	found, err = r.Get("stable", &incompatible)
	if err == nil || !found { t.Fatalf("incompatible decode: found=%v err=%v", found, err) }
	if r.Delete("") || r.Has("") { t.Fatal("empty key reported present or deleted") }
}

func TestRegistryKeysDeleteAndSliceIsolation(t *testing.T) {
	r := NewRegistry()
	if keys := r.Keys(); len(keys) != 0 { t.Fatalf("empty Keys=%#v", keys) }
	for _, k := range []string{"z", "a", "m"} {
		if err := r.Put(k, k); err != nil { t.Fatal(err) }
	}
	keys := r.Keys()
	if !reflect.DeepEqual(keys, []string{"a", "m", "z"}) { t.Fatalf("Keys=%v", keys) }
	keys[0] = "corrupt"
	if !reflect.DeepEqual(r.Keys(), []string{"a", "m", "z"}) { t.Fatal("Keys slice aliases metadata") }
	if !r.Has("m") || !r.Delete("m") || r.Delete("m") || r.Has("m") { t.Fatal("delete/has semantics incorrect") }
}

func TestRegistryConcurrentCalls(t *testing.T) {
	r := NewRegistry()
	const writers = 20
	const readers = 4
	start := make(chan struct{})
	var wg sync.WaitGroup

	for i := 0; i < writers; i++ {
		i := i
		wg.Add(1)
		go func() {
			defer wg.Done()
			<-start
			key := fmt.Sprintf("k%02d", i)
			if err := r.Put(key, i); err != nil { t.Errorf("initial Put %q: %v", key, err); return }
			var got int
			if found, err := r.Get(key, &got); err != nil || !found || got != i { t.Errorf("initial Get %q: found=%v value=%d err=%v", key, found, got, err) }
			if !r.Has(key) { t.Errorf("Has %q false after Put", key) }
			if err := r.Put(key, i+100); err != nil { t.Errorf("replacement Put %q: %v", key, err); return }
			got = -1
			if found, err := r.Get(key, &got); err != nil || !found || got != i+100 { t.Errorf("replacement Get %q: found=%v value=%d err=%v", key, found, got, err) }
			if !r.Delete(key) { t.Errorf("Delete %q reported absent", key) }
			got = 77
			if found, err := r.Get(key, &got); err != nil || found || got != 77 { t.Errorf("absent Get %q: found=%v value=%d err=%v", key, found, got, err) }
			if err := r.Put(key, i+1000); err != nil { t.Errorf("final Put %q: %v", key, err) }
		}()
	}

	for i := 0; i < readers; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			<-start
			for j := 0; j < 40; j++ {
				keys := r.Keys()
				if !sort.StringsAreSorted(keys) { t.Errorf("Keys not sorted: %v", keys); return }
				for k := 1; k < len(keys); k++ {
					if keys[k-1] == keys[k] { t.Errorf("duplicate key in snapshot: %v", keys); return }
				}
			}
		}()
	}

	close(start)
	wg.Wait()

	wantKeys := make([]string, writers)
	for i := 0; i < writers; i++ { wantKeys[i] = fmt.Sprintf("k%02d", i) }
	if got := r.Keys(); !reflect.DeepEqual(got, wantKeys) { t.Fatalf("final Keys=%v want=%v", got, wantKeys) }
	for i, key := range wantKeys {
		var got int
		found, err := r.Get(key, &got)
		if err != nil || !found || got != i+1000 { t.Fatalf("final Get %q: found=%v value=%d err=%v", key, found, got, err) }
	}
}

