package solution

import (
	"errors"
	"reflect"
	"testing"
)

func TestRunWeightedStopsOnSuccess(t *testing.T) {
	calls := 0
	used, err := RunWeighted(5, 3, func(weight int) error {
		calls++
		if calls == 3 { return nil }
		return errors.New("retry")
	})
	if err != nil { t.Fatal(err) }
	if !reflect.DeepEqual(used, []int{3, 6, 12}) { t.Fatalf("used=%v", used) }
	if calls != 3 { t.Fatalf("calls=%d", calls) }
}

func TestRunWeightedNativeMaxAttemptsCanStopImmediately(t *testing.T) {
	maxInt := int(^uint(0) >> 1)
	calls := 0
	used, err := RunWeighted(maxInt, 1, func(weight int) error {
		calls++
		if weight != 1 { t.Fatalf("first weight=%d", weight) }
		return nil
	})
	if err != nil || calls != 1 || !reflect.DeepEqual(used, []int{1}) { t.Fatalf("used=%v err=%v calls=%d", used, err, calls) }
}

func TestRunWeightedReturnsFinalError(t *testing.T) {
	errs := []error{errors.New("one"), errors.New("two"), errors.New("final")}
	i := 0
	used, err := RunWeighted(3, 1, func(int) error { e := errs[i]; i++; return e })
	if !reflect.DeepEqual(used, []int{1, 2, 4}) { t.Fatalf("used=%v", used) }
	if err != errs[2] { t.Fatalf("returned error %v, want final error identity", err) }
}

func TestRunWeightedSaturatesAtMaxInt(t *testing.T) {
	maxInt := int(^uint(0) >> 1)
	start := maxInt/2 + 1
	used, err := RunWeighted(4, start, func(int) error { return errors.New("fail") })
	if err == nil { t.Fatal("expected final error") }
	want := []int{start, maxInt, maxInt, maxInt}
	if !reflect.DeepEqual(used, want) { t.Fatalf("used=%v want=%v", used, want) }
}

func TestRunWeightedInvalidInputDoesNotInvoke(t *testing.T) {
	calls := 0
	action := func(int) error { calls++; return nil }
	cases := []struct {
		attempts int
		weight int
		action func(int) error
	}{{0, 1, action}, {-1, 1, action}, {1, 0, action}, {1, -1, action}, {1, 1, nil}}
	for _, tc := range cases {
		used, err := RunWeighted(tc.attempts, tc.weight, tc.action)
		if err == nil || used != nil { t.Errorf("invalid result: used=%#v err=%v", used, err) }
	}
	if calls != 0 { t.Fatalf("action invoked %d times", calls) }
}

func TestRunWeightedDoesNotRecoverPanic(t *testing.T) {
	marker := errors.New("panic marker")
	defer func() {
		if recover() != marker { t.Fatal("action panic was recovered or changed") }
	}()
	_, _ = RunWeighted(1, 1, func(int) error { panic(marker) })
}

