package solution

import (
	"reflect"
	"strings"
	"testing"
)

func TestNoteCreateValidationAndConsecutiveIDs(t *testing.T) {
	s := NewNoteStore()
	invalid := []struct{ topic, text string }{
		{"", "x"}, {"x", ""}, {" x", "y"}, {"x ", "y"}, {"x", " y"}, {"x", "y\n"},
		{strings.Repeat("a", 41), "x"}, {"x", strings.Repeat("b", 501)},
		{strings.Repeat("é", 21), "x"},
	}
	for _, tc := range invalid {
		if _, err := s.Create(tc.topic, tc.text); err != ErrInvalidNote { t.Errorf("Create(%q,%q) error=%v", tc.topic, tc.text, err) }
	}
	first, err := s.Create(strings.Repeat("a", 40), strings.Repeat("b", 500))
	if err != nil || first.ID != 1 { t.Fatalf("boundary create=%+v,%v", first, err) }
	second, err := s.Create("topic", "text")
	if err != nil || second.ID != 2 { t.Fatalf("second create=%+v,%v", second, err) }
}

func TestNoteUpdateGetDeleteErrors(t *testing.T) {
	s := NewNoteStore()
	n, _ := s.Create("old", "body")
	if got, err := s.Update(n.ID, "new", "updated"); err != nil || got != (Note{ID: n.ID, Topic: "new", Text: "updated"}) { t.Fatalf("Update=%+v,%v", got, err) }
	if got, err := s.Get(n.ID); err != nil || got.Topic != "new" { t.Fatalf("Get=%+v,%v", got, err) }

	if _, err := s.Update(n.ID, " bad", "x"); err != ErrInvalidNote { t.Fatalf("invalid update error=%v", err) }
	if got, _ := s.Get(n.ID); got.Topic != "new" { t.Fatal("invalid update changed note") }
	for _, id := range []int{0, -1} {
		if _, err := s.Update(id, "a", "b"); err != ErrInvalidNote { t.Errorf("Update id %d: %v", id, err) }
		if _, err := s.Get(id); err != ErrInvalidNote { t.Errorf("Get id %d: %v", id, err) }
		if err := s.Delete(id); err != ErrInvalidNote { t.Errorf("Delete id %d: %v", id, err) }
	}
	if _, err := s.Update(999, "a", "b"); err != ErrNoteNotFound { t.Fatalf("missing Update: %v", err) }
	if _, err := s.Get(999); err != ErrNoteNotFound { t.Fatalf("missing Get: %v", err) }
	if err := s.Delete(999); err != ErrNoteNotFound { t.Fatalf("missing Delete: %v", err) }
	if err := s.Delete(n.ID); err != nil { t.Fatal(err) }
	if _, err := s.Get(n.ID); err != ErrNoteNotFound { t.Fatalf("deleted Get: %v", err) }
}

func TestNoteDeleteManyAtomicPrecedenceAndDuplicates(t *testing.T) {
	s := NewNoteStore()
	a, _ := s.Create("t", "a")
	b, _ := s.Create("t", "b")
	c, _ := s.Create("t", "c")
	missing := 999

	mixed := [][]int{
		{a.ID, missing, 0},
		{0, a.ID, missing},
		{missing, -1, a.ID},
		{a.ID, -1, missing},
	}
	for _, ids := range mixed {
		if err := s.DeleteMany(ids); err != ErrInvalidNote { t.Errorf("DeleteMany(%v) error=%v", ids, err) }
		for _, id := range []int{a.ID, b.ID, c.ID} {
			if _, err := s.Get(id); err != nil { t.Fatalf("mixed invalid batch %v deleted %d", ids, id) }
		}
	}

	if err := s.DeleteMany([]int{a.ID, missing, c.ID}); err != ErrNoteNotFound { t.Fatalf("all-positive missing batch: %v", err) }
	for _, id := range []int{a.ID, b.ID, c.ID} {
		if _, err := s.Get(id); err != nil { t.Fatalf("missing batch partially deleted %d", id) }
	}

	if err := s.DeleteMany(nil); err != nil { t.Fatalf("empty batch: %v", err) }
	if err := s.DeleteMany([]int{a.ID, a.ID, c.ID}); err != nil { t.Fatalf("duplicate batch: %v", err) }
	if _, err := s.Get(a.ID); err != ErrNoteNotFound { t.Fatal("a remains") }
	if _, err := s.Get(c.ID); err != ErrNoteNotFound { t.Fatal("c remains") }
	if got, err := s.Get(b.ID); err != nil || got.Text != "b" { t.Fatalf("b changed: %+v %v", got, err) }
}

func TestNoteListFilteringOrderingPagination(t *testing.T) {
	s := NewNoteStore()
	for _, x := range []struct{ topic, text string }{{"A", "one"}, {"B", "two"}, {"A", "three"}, {"a", "four"}, {"A", "five"}} {
		if _, err := s.Create(x.topic, x.text); err != nil { t.Fatal(err) }
	}
	got, err := s.List("A", 1, 2)
	if err != nil { t.Fatal(err) }
	want := []Note{{ID: 3, Topic: "A", Text: "three"}, {ID: 5, Topic: "A", Text: "five"}}
	if !reflect.DeepEqual(got, want) { t.Fatalf("filtered page=%+v", got) }
	all, err := s.List("", 0, 100)
	if err != nil || len(all) != 5 { t.Fatalf("all=%+v,%v", all, err) }
	for i, n := range all {
		if n.ID != i+1 { t.Fatalf("not ordered: %+v", all) }
	}

	empty, err := s.List("A", 3, 1)
	if err != nil || empty == nil || len(empty) != 0 { t.Fatalf("boundary empty=%#v,%v", empty, err) }
	empty, err = s.List("missing", 0, 1)
	if err != nil || empty == nil || len(empty) != 0 { t.Fatalf("no matches=%#v,%v", empty, err) }

	got[0].Topic = "changed"
	again, _ := s.Get(3)
	if again.Topic != "A" { t.Fatal("List result exposed store state") }
}

func TestNoteListInvalidPage(t *testing.T) {
	s := NewNoteStore()
	for _, tc := range [][2]int{{-1, 1}, {0, 0}, {0, -1}, {0, 101}} {
		got, err := s.List("", tc[0], tc[1])
		if err != ErrInvalidPage || got != nil { t.Errorf("List(%d,%d)=%#v,%v", tc[0], tc[1], got, err) }
	}
	if got, err := s.List("", 0, 1); err != nil || got == nil { t.Fatalf("minimum limit=%#v,%v", got, err) }
}

