package solution

import (
	"errors"
	"sort"
	"strings"
	"sync"
)

type ClusterRecord struct {
	Namespace string
	Name      string
	Replicas  int
}

type recordKey struct {
	namespace string
	name      string
}

type Reconciler struct {
	mu      sync.RWMutex
	all     bool
	leader  bool
	watched map[string]struct{}
	records map[recordKey]ClusterRecord
}

func NewReconciler(watch string, leader bool) (*Reconciler, error) {
	r := &Reconciler{
		leader:  leader,
		watched: make(map[string]struct{}),
		records: make(map[recordKey]ClusterRecord),
	}
	if watch == "" {
		r.all = true
		return r, nil
	}
	for _, part := range strings.Split(watch, ",") {
		name := strings.TrimSpace(part)
		if name == "" {
			return nil, errors.New("watch contains an empty namespace")
		}
		r.watched[name] = struct{}{}
	}
	return r, nil
}

func (r *Reconciler) Apply(record ClusterRecord, deleted bool) (bool, error) {
	if record.Namespace == "" || record.Name == "" {
		return false, errors.New("namespace and name are required")
	}
	if record.Replicas < 0 {
		return false, errors.New("replicas cannot be negative")
	}

	r.mu.Lock()
	defer r.mu.Unlock()
	if !r.leader {
		return false, errors.New("reconciler is not the leader")
	}
	if !r.all {
		if _, ok := r.watched[record.Namespace]; !ok {
			return false, nil
		}
	}
	key := recordKey{namespace: record.Namespace, name: record.Name}
	if deleted {
		delete(r.records, key)
	} else {
		r.records[key] = record
	}
	return true, nil
}

func (r *Reconciler) Snapshot() []ClusterRecord {
	r.mu.RLock()
	out := make([]ClusterRecord, 0, len(r.records))
	for _, record := range r.records {
		out = append(out, record)
	}
	r.mu.RUnlock()
	sort.Slice(out, func(i, j int) bool {
		if out[i].Namespace != out[j].Namespace {
			return out[i].Namespace < out[j].Namespace
		}
		return out[i].Name < out[j].Name
	})
	return out
}

