package solution

import (
	"fmt"
	"reflect"
	"sort"
	"sync"
	"testing"
)

func TestReconcilerWatchParsingAndFiltering(t *testing.T) {
	for _, watch := range []string{"a,", ",a", "a,,b", "a,   ,b"} {
		if _, err := NewReconciler(watch, true); err == nil { t.Errorf("NewReconciler(%q) succeeded", watch) }
	}
	r, err := NewReconciler(" ns-b, ns-a,ns-a ", true)
	if err != nil { t.Fatal(err) }
	handled, err := r.Apply(ClusterRecord{Namespace: "ns-a", Name: "app", Replicas: 1}, false)
	if err != nil || !handled { t.Fatalf("watched Apply=%v,%v", handled, err) }
	handled, err = r.Apply(ClusterRecord{Namespace: "other", Name: "ignored", Replicas: 2}, false)
	if err != nil || handled { t.Fatalf("unwatched Apply=%v,%v", handled, err) }
	if got := r.Snapshot(); !reflect.DeepEqual(got, []ClusterRecord{{Namespace: "ns-a", Name: "app", Replicas: 1}}) { t.Fatalf("Snapshot=%+v", got) }
}

func TestReconcilerEmptyWatchReplaceDeleteAndIsolation(t *testing.T) {
	r, err := NewReconciler("", true)
	if err != nil { t.Fatal(err) }
	for _, record := range []ClusterRecord{
		{Namespace: "z", Name: "b", Replicas: 1},
		{Namespace: "a", Name: "z", Replicas: 2},
		{Namespace: "a", Name: "a", Replicas: 3},
	} {
		if handled, err := r.Apply(record, false); err != nil || !handled { t.Fatalf("Apply=%v,%v", handled, err) }
	}
	if handled, err := r.Apply(ClusterRecord{Namespace: "a", Name: "a", Replicas: 0}, false); err != nil || !handled { t.Fatalf("replace=%v,%v", handled, err) }
	want := []ClusterRecord{{Namespace: "a", Name: "a", Replicas: 0}, {Namespace: "a", Name: "z", Replicas: 2}, {Namespace: "z", Name: "b", Replicas: 1}}
	got := r.Snapshot()
	if !reflect.DeepEqual(got, want) { t.Fatalf("sorted Snapshot=%+v", got) }
	got[0].Name = "corrupt"
	if !reflect.DeepEqual(r.Snapshot(), want) { t.Fatal("Snapshot aliases state") }

	if handled, err := r.Apply(ClusterRecord{Namespace: "a", Name: "a", Replicas: 999}, true); err != nil || !handled { t.Fatalf("delete=%v,%v", handled, err) }
	if handled, err := r.Apply(ClusterRecord{Namespace: "missing", Name: "x", Replicas: 0}, true); err != nil || !handled { t.Fatalf("missing delete=%v,%v", handled, err) }
}

func TestReconcilerStructuralKeysSupportNUL(t *testing.T) {
	r, err := NewReconciler("", true)
	if err != nil { t.Fatal(err) }
	first := ClusterRecord{Namespace: "a\u0000b", Name: "c", Replicas: 1}
	second := ClusterRecord{Namespace: "a", Name: "b\u0000c", Replicas: 2}
	for _, record := range []ClusterRecord{first, second} {
		if handled, err := r.Apply(record, false); err != nil || !handled { t.Fatalf("Apply(%+v)=%v,%v", record, handled, err) }
	}
	want := []ClusterRecord{second, first}
	if got := r.Snapshot(); !reflect.DeepEqual(got, want) { t.Fatalf("NUL keys collided or sorted incorrectly: %+v", got) }

	first.Replicas = 7
	if handled, err := r.Apply(first, false); err != nil || !handled { t.Fatalf("replace=%v,%v", handled, err) }
	if handled, err := r.Apply(second, true); err != nil || !handled { t.Fatalf("delete=%v,%v", handled, err) }
	if got := r.Snapshot(); !reflect.DeepEqual(got, []ClusterRecord{first}) { t.Fatalf("independent structural key changed: %+v", got) }
}

func TestReconcilerValidationAndLeadershipDoNotChangeState(t *testing.T) {
	r, _ := NewReconciler("", true)
	_, _ = r.Apply(ClusterRecord{Namespace: "n", Name: "ok", Replicas: 1}, false)
	before := r.Snapshot()
	invalid := []ClusterRecord{{Namespace: "", Name: "x", Replicas: 1}, {Namespace: "n", Name: "", Replicas: 1}, {Namespace: "n", Name: "x", Replicas: -1}}
	for _, record := range invalid {
		if handled, err := r.Apply(record, false); err == nil || handled { t.Errorf("invalid Apply(%+v)=%v,%v", record, handled, err) }
		if !reflect.DeepEqual(r.Snapshot(), before) { t.Fatal("invalid Apply changed state") }
	}

	follower, err := NewReconciler("n", false)
	if err != nil { t.Fatal(err) }
	if handled, err := follower.Apply(ClusterRecord{Namespace: "n", Name: "x", Replicas: 1}, false); err == nil || handled { t.Fatalf("follower Apply=%v,%v", handled, err) }
	if len(follower.Snapshot()) != 0 { t.Fatal("follower changed state") }
	if handled, err := follower.Apply(ClusterRecord{Namespace: "outside", Name: "x", Replicas: 1}, false); err == nil || handled { t.Fatalf("leadership must be checked before watch filtering: %v,%v", handled, err) }
}

func TestReconcilerConcurrentUse(t *testing.T) {
	r, _ := NewReconciler("", true)
	const writers = 30
	const readers = 4
	start := make(chan struct{})
	var wg sync.WaitGroup

	for i := 0; i < writers; i++ {
		i := i
		wg.Add(1)
		go func() {
			defer wg.Done()
			<-start
			record := ClusterRecord{Namespace: fmt.Sprintf("ns%02d", i%3), Name: fmt.Sprintf("name%02d", i), Replicas: i}
			if handled, err := r.Apply(record, false); err != nil || !handled { t.Errorf("insert %d: %v,%v", i, handled, err); return }
			record.Replicas = i + 100
			if handled, err := r.Apply(record, false); err != nil || !handled { t.Errorf("replace %d: %v,%v", i, handled, err); return }
			if handled, err := r.Apply(record, true); err != nil || !handled { t.Errorf("delete %d: %v,%v", i, handled, err); return }
			record.Replicas = i + 1000
			if handled, err := r.Apply(record, false); err != nil || !handled { t.Errorf("final insert %d: %v,%v", i, handled, err) }
		}()
	}

	for i := 0; i < readers; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			<-start
			for j := 0; j < 50; j++ {
				snapshot := r.Snapshot()
				seen := make(map[[2]string]struct{}, len(snapshot))
				for k, record := range snapshot {
					key := [2]string{record.Namespace, record.Name}
					if _, exists := seen[key]; exists { t.Errorf("duplicate structural key: %+v", key); return }
					seen[key] = struct{}{}
					if k > 0 {
						previous := snapshot[k-1]
						if previous.Namespace > record.Namespace || (previous.Namespace == record.Namespace && previous.Name > record.Name) {
							t.Errorf("unsorted snapshot: %+v", snapshot)
							return
						}
					}
				}
			}
		}()
	}

	close(start)
