package solution

import (
	"errors"
	"reflect"
	"testing"
)

func TestRunPlanDeterministicDependencyExecution(t *testing.T) {
	steps := []Step{
		{Name: "third", Requires: []string{"first", "second"}},
		{Name: "second", Requires: []string{"first"}},
		{Name: "independent"},
		{Name: "first"},
	}
	before := cloneSteps(steps)
	var calls []string
	got, err := RunPlan(steps, func(name string) error { calls = append(calls, name); return nil })
	if err != nil { t.Fatal(err) }
	wantCalls := []string{"independent", "first", "second", "third"}
	if !reflect.DeepEqual(calls, wantCalls) { t.Fatalf("calls=%v", calls) }
	want := []StepOutcome{
		{Name: "independent", Status: "succeeded"},
		{Name: "first", Status: "succeeded"},
		{Name: "second", Status: "succeeded"},
		{Name: "third", Status: "succeeded"},
	}
	if !reflect.DeepEqual(got, want) { t.Fatalf("outcomes=%+v", got) }
	if !reflect.DeepEqual(steps, before) { t.Fatal("steps mutated") }
}

func TestRunPlanNewlyReadyEarlierStepWins(t *testing.T) {
	steps := []Step{
		{Name: "a", Requires: []string{"b"}},
		{Name: "b"},
		{Name: "c"},
	}
	var calls []string
	got, err := RunPlan(steps, func(name string) error { calls = append(calls, name); return nil })
	if err != nil { t.Fatal(err) }
	if !reflect.DeepEqual(calls, []string{"b", "a", "c"}) { t.Fatalf("calls=%v", calls) }
	want := []StepOutcome{{Name: "b", Status: "succeeded"}, {Name: "a", Status: "succeeded"}, {Name: "c", Status: "succeeded"}}
	if !reflect.DeepEqual(got, want) { t.Fatalf("outcomes=%+v", got) }

	steps = []Step{{Name: "early1", Requires: []string{"root"}}, {Name: "early2", Requires: []string{"root"}}, {Name: "root"}, {Name: "late"}}
	calls = nil
	got, err = RunPlan(steps, func(name string) error { calls = append(calls, name); return nil })
	if err != nil { t.Fatal(err) }
	if !reflect.DeepEqual(calls, []string{"root", "early1", "early2", "late"}) { t.Fatalf("multiple newly ready calls=%v", calls) }
	for i, name := range calls {
		if got[i] != (StepOutcome{Name: name, Status: "succeeded"}) { t.Fatalf("outcomes=%+v", got) }
	}
}

func TestRunPlanFailureSkipsTransitiveDependentsAndContinues(t *testing.T) {
	boom := errors.New("boom")
	steps := []Step{
		{Name: "root"},
		{Name: "direct", Requires: []string{"root"}},
		{Name: "transitive", Requires: []string{"direct"}},
		{Name: "free"},
	}
	var calls []string
	got, err := RunPlan(steps, func(name string) error {
		calls = append(calls, name)
		if name == "root" { return boom }
		return nil
	})
	if err != nil { t.Fatalf("callback failure became RunPlan error: %v", err) }
	if !reflect.DeepEqual(calls, []string{"root", "free"}) { t.Fatalf("calls=%v", calls) }
	assertOutcomesByName(t, got, map[string]StepOutcome{
		"root": {Name: "root", Status: "failed", Error: "boom"},
		"direct": {Name: "direct", Status: "skipped"},
		"transitive": {Name: "transitive", Status: "skipped"},
		"free": {Name: "free", Status: "succeeded"},
	})
}

func TestRunPlanFailedAndSuccessfulDependenciesSkipJoin(t *testing.T) {
	steps := []Step{{Name: "bad"}, {Name: "good"}, {Name: "join", Requires: []string{"bad", "good"}}}
	var calls []string
	got, err := RunPlan(steps, func(name string) error {
		calls = append(calls, name)
		if name == "bad" { return errors.New("failed") }
		return nil
	})
	if err != nil { t.Fatal(err) }
	if !reflect.DeepEqual(calls, []string{"bad", "good"}) { t.Fatalf("calls=%v", calls) }
	assertOutcomesByName(t, got, map[string]StepOutcome{
		"bad": {Name: "bad", Status: "failed", Error: "failed"},
		"good": {Name: "good", Status: "succeeded"},
		"join": {Name: "join", Status: "skipped"},
	})
}

func TestRunPlanEmpty(t *testing.T) {
	got, err := RunPlan(nil, func(string) error { t.Fatal("called"); return nil })
	if err != nil || got == nil || len(got) != 0 { t.Fatalf("empty plan=%#v,%v", got, err) }
}

func TestRunPlanRejectsNilExecute(t *testing.T) {
	if _, err := RunPlan(nil, nil); err == nil { t.Fatal("nil execute accepted") }
}

func TestRunPlanStructuralValidationBeforeExecution(t *testing.T) {
	cases := [][]Step{
		{{Name: ""}},
		{{Name: " x"}},
		{{Name: "x "}},
		{{Name: "x", Requires: []string{""}}},
		{{Name: "x", Requires: []string{" y"}}, {Name: "y"}},
		{{Name: "x"}, {Name: "x"}},
		{{Name: "x", Requires: []string{"y", "y"}}, {Name: "y"}},
		{{Name: "x", Requires: []string{"missing"}}},
		{{Name: "x", Requires: []string{"x"}}},
		{{Name: "a", Requires: []string{"b"}}, {Name: "b", Requires: []string{"a"}}},
		{{Name: "a", Requires: []string{"b"}}, {Name: "b", Requires: []string{"c"}}, {Name: "c", Requires: []string{"a"}}},
	}
	for i, steps := range cases {
		calls := 0
		before := cloneSteps(steps)
		_, err := RunPlan(steps, func(string) error { calls++; return nil })
		if err == nil { t.Errorf("case %d accepted", i) }
		if calls != 0 { t.Errorf("case %d invoked callback %d times", i, calls) }
		if !reflect.DeepEqual(steps, before) { t.Errorf("case %d mutated input", i) }
	}
}

func assertOutcomesByName(t *testing.T, got []StepOutcome, want map[string]StepOutcome) {
	t.Helper()
	if len(got) != len(want) { t.Fatalf("outcomes=%+v", got) }
	seen := make(map[string]bool, len(got))
	for _, outcome := range got {
		if seen[outcome.Name] { t.Fatalf("duplicate outcome for %q: %+v", outcome.Name, got) }
		seen[outcome.Name] = true
		if expected, ok := want[outcome.Name]; !ok || outcome != expected { t.Fatalf("unexpected outcome %+v; all=%+v", outcome, got) }
	}
}

func cloneSteps(in []Step) []Step {
	out := make([]Step, len(in))
	for i, step := range in {
		out[i] = Step{Name: step.Name, Requires: append([]string(nil), step.Requires...)}
	}
	return out
}

