import java.util.*;

public class SolutionTest {
    public static void main(String[] args) throws Exception {
        eq(" body ", Solution.parse(" body ", " Text/Plain ; charset=UTF-8", String.class, Collections.emptyList()));
        eq(Integer.valueOf(42), Solution.parse(" 42 ", "application/integer", Integer.class, Collections.emptyList()));
        eq(Boolean.TRUE, Solution.parse(" TrUe ", "APPLICATION/BOOLEAN;v=1", Boolean.class, Collections.emptyList()));
        eq(Boolean.FALSE, Solution.parse("false", "application/boolean", Boolean.class, Collections.emptyList()));

        List<String> calls = new ArrayList<>();
        Solution.TextConversion first = new Solution.TextConversion() {
            public boolean supports(String mediaType, Class<?> targetType) {
                calls.add("first:" + mediaType);
                return true;
            }
            public Object convert(String body) { calls.add("convert1"); return "custom:" + body; }
        };
        Solution.TextConversion second = new Solution.TextConversion() {
            public boolean supports(String mediaType, Class<?> targetType) { calls.add("second"); return true; }
            public Object convert(String body) { throw new AssertionError("must not run"); }
        };
        List<Solution.TextConversion> conversions = Collections.unmodifiableList(Arrays.asList(first, second));
        eq("custom:x", Solution.parse("x", " X/THING ; p=q", String.class, conversions));
        eq(Arrays.asList("first:x/thing", "convert1"), calls);

        Solution.TextConversion nullResult = new Solution.TextConversion() {
            public boolean supports(String m, Class<?> t) { return true; }
            public Object convert(String b) { return null; }
        };
        if (Solution.parse("x", "x/y", Integer.class, Collections.singletonList(nullResult)) != null)
            throw new AssertionError("null custom result must be accepted");

        Solution.TextConversion wrong = new Solution.TextConversion() {
            public boolean supports(String m, Class<?> t) { return true; }
            public Object convert(String b) { return Long.valueOf(1); }
        };
        expectParse(null, () -> Solution.parse("1", "x/y", Integer.class, Collections.singletonList(wrong)));

        RuntimeException boom = new RuntimeException("boom");
        Solution.TextConversion throwing = new Solution.TextConversion() {
            public boolean supports(String m, Class<?> t) { return true; }
            public Object convert(String b) { throw boom; }
        };
        expectParse(boom, () -> Solution.parse("x", "x/y", String.class, Collections.singletonList(throwing)));

        RuntimeException supportBoom = new RuntimeException("support");
        Solution.TextConversion badSupport = new Solution.TextConversion() {
            public boolean supports(String m, Class<?> t) { throw supportBoom; }
            public Object convert(String b) { return b; }
        };
        expectParse(supportBoom, () -> Solution.parse("x", "x/y", String.class, Collections.singletonList(badSupport)));

        expectParse(null, () -> Solution.parse("2147483648", "application/integer", Integer.class, Collections.emptyList()));
        expectParse(null, () -> Solution.parse("yes", "application/boolean", Boolean.class, Collections.emptyList()));
        expectParse(null, () -> Solution.parse("x", "text/plain", Object.class, Collections.emptyList()));
        expectParse(null, () -> Solution.parse("x", "unknown/type", String.class, Collections.emptyList()));

        expectIae(() -> Solution.parse(null, "text/plain", String.class, Collections.emptyList()));
        expectIae(() -> Solution.parse("x", null, String.class, Collections.emptyList()));
        expectIae(() -> Solution.parse("x", "text/plain", null, Collections.emptyList()));
        expectIae(() -> Solution.parse("x", "text/plain", String.class, null));
        List<Solution.TextConversion> withNull = new ArrayList<>();
        withNull.add(null);
        expectIae(() -> Solution.parse("x", "text/plain", String.class, withNull));
    }

    private interface Checked { void run() throws Exception; }
    private static void expectParse(Throwable cause, Checked action) throws Exception {
        try { action.run(); throw new AssertionError("expected ParseException"); }
        catch (Solution.ParseException ex) {
            if (cause != null && ex.getCause() != cause) throw new AssertionError("runtime cause not preserved");
        }
    }
    private static void expectIae(Checked action) {
        try { action.run(); throw new AssertionError("expected IllegalArgumentException"); }
        catch (IllegalArgumentException expected) { }
        catch (Exception other) { throw new AssertionError(other); }
    }
    private static void eq(Object expected, Object actual) {
        if (!Objects.equals(expected, actual)) throw new AssertionError("expected=" + expected + " actual=" + actual);
    }
}

