import java.util.*;

public class SolutionTest {
    public static void main(String[] args) {
        Solution.Catalog empty = Solution.emptyCatalog();
        eq(0, Solution.list(empty).size());
        eq(null, Solution.urlOf(empty, "missing"));
        expectUoe(() -> Solution.list(empty).add(null));

        Solution.Catalog c1 = Solution.add(empty, "b", " url b ");
        Solution.Catalog c2 = Solution.add(c1, "a", "url-a");
        Solution.Catalog c3 = Solution.add(c2, " ", " ");
        eq(0, Solution.list(empty).size());
        eq(1, Solution.list(c1).size());
        assertProducts(Solution.list(c3), new String[]{" ", "a", "b"}, new String[]{" ", "url-a", " url b "});
        eq(" url b ", Solution.urlOf(c3, "b"));

        List<Solution.Product> snapshot = Solution.list(c3);
        Solution.Catalog changed = Solution.changeUrl(c3, "a", "new-a");
        eq("url-a", Solution.urlOf(c3, "a"));
        eq("new-a", Solution.urlOf(changed, "a"));
        assertProducts(snapshot, new String[]{" ", "a", "b"}, new String[]{" ", "url-a", " url b "});
        expectUoe(() -> snapshot.remove(0));

        Solution.Catalog removed = Solution.remove(changed, "b");
        eq(null, Solution.urlOf(removed, "b"));
        eq(" url b ", Solution.urlOf(changed, "b"));
        assertProducts(Solution.list(removed), new String[]{" ", "a"}, new String[]{" ", "new-a"});

        expectIae(() -> Solution.add(c3, "a", "other"));
        expectIae(() -> Solution.remove(c3, "absent"));
        expectIae(() -> Solution.changeUrl(c3, "absent", "x"));
        expectIae(() -> Solution.add(null, "x", "y"));
        expectIae(() -> Solution.add(empty, null, "y"));
        expectIae(() -> Solution.add(empty, "", "y"));
        expectIae(() -> Solution.add(empty, "x", null));
        expectIae(() -> Solution.add(empty, "x", ""));
        expectIae(() -> Solution.remove(null, "x"));
        expectIae(() -> Solution.remove(empty, null));
        expectIae(() -> Solution.remove(empty, ""));
        expectIae(() -> Solution.changeUrl(null, "x", "y"));
        expectIae(() -> Solution.changeUrl(c3, "a", ""));
        expectIae(() -> Solution.changeUrl(c3, "a", null));
        expectIae(() -> Solution.urlOf(null, "x"));
        expectIae(() -> Solution.urlOf(empty, ""));
        expectIae(() -> Solution.list(null));
    }

    private static void assertProducts(List<Solution.Product> list, String[] codes, String[] urls) {
        eq(codes.length, list.size());
        for (int i = 0; i < codes.length; i++) {
            eq(codes[i], list.get(i).getCode());
            eq(urls[i], list.get(i).getUrl());
        }
    }
    private static void eq(Object expected, Object actual) {
        if (!Objects.equals(expected, actual)) throw new AssertionError("expected=" + expected + " actual=" + actual);
    }
    private static void expectIae(Runnable r) {
        try { r.run(); throw new AssertionError("expected IllegalArgumentException"); }
        catch (IllegalArgumentException expected) { }
    }
    private static void expectUoe(Runnable r) {
        try { r.run(); throw new AssertionError("expected UnsupportedOperationException"); }
        catch (UnsupportedOperationException expected) { }
    }
}

