        }
        Map<String, String> data = new HashMap<>(catalog.data);
        data.put(code, url);
        return new Catalog(data);
    }

    public static Catalog remove(Catalog catalog, String code) {
        checkCode(catalog, code);
        if (!catalog.data.containsKey(code)) {
            throw new IllegalArgumentException();
        }
        Map<String, String> data = new HashMap<>(catalog.data);
        data.remove(code);
        return new Catalog(data);
    }

    public static Catalog changeUrl(Catalog catalog, String code, String url) {
        check(catalog, code, url);
        if (!catalog.data.containsKey(code)) {
            throw new IllegalArgumentException();
        }
        Map<String, String> data = new HashMap<>(catalog.data);
        data.put(code, url);
        return new Catalog(data);
    }

    public static String urlOf(Catalog catalog, String code) {
        checkCode(catalog, code);
        return catalog.data.get(code);
    }

    public static List<Product> list(Catalog catalog) {
        if (catalog == null) {
            throw new IllegalArgumentException();
        }
        List<String> codes = new ArrayList<>(catalog.data.keySet());
        Collections.sort(codes);
        List<Product> products = new ArrayList<>(codes.size());
        for (String code : codes) {
            products.add(new Product(code, catalog.data.get(code)));
        }
        return Collections.unmodifiableList(products);
    }

    private static void check(Catalog catalog, String code, String url) {
        checkCode(catalog, code);
        if (url == null || url.isEmpty()) {
            throw new IllegalArgumentException();
        }
    }

    private static void checkCode(Catalog catalog, String code) {
        if (catalog == null || code == null || code.isEmpty()) {
            throw new IllegalArgumentException();
        }
    }
}

