import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;

public class SolutionTest {
    public static void main(String[] args) throws Exception {
        Solution.Note note = new Solution.Note("  id  ", Long.MAX_VALUE, "  alice  ",
                Solution.PayloadKind.TEXT, "a|b");
        eq("id", note.id());
        eq(Long.MAX_VALUE, note.timestamp());
        eq("alice", note.sender());
        eq(Solution.PayloadKind.TEXT, note.kind());
        eq("a|b", note.content());
        eq(Solution.DeliveryState.NEW, note.state());
        no(note.isRead());
        eq("TEXT|a|b|alice|NEW|read=false", note.toString());
        no(note.deliver());
        no(note.markRead());
        yes(note.beginSend());
        no(note.beginSend());
        eq(Solution.DeliveryState.SENDING, note.state());
        yes(note.deliver());
        no(note.deliver());
        no(note.fail());
        yes(note.markRead());
        no(note.markRead());
        eq("TEXT|a|b|alice|DELIVERED|read=true", note.toString());

        Solution.Note failedNew = new Solution.Note("x", 0, "s", Solution.PayloadKind.IMAGE, "");
        yes(failedNew.fail());
        no(failedNew.fail());
        no(failedNew.beginSend());
        no(failedNew.deliver());
        no(failedNew.markRead());
        eq(Solution.DeliveryState.FAILED, failedNew.state());

        Solution.Note failedSending = new Solution.Note("x2", 1, "s", Solution.PayloadKind.SOUND, "content");
        yes(failedSending.beginSend());
        yes(failedSending.fail());
        no(failedSending.deliver());

        expectIae(() -> new Solution.Note(null, 0, "s", Solution.PayloadKind.TEXT, ""));
        expectIae(() -> new Solution.Note(" \u2003 ", 0, "s", Solution.PayloadKind.TEXT, ""));
        expectIae(() -> new Solution.Note("x", -1, "s", Solution.PayloadKind.TEXT, ""));
        expectIae(() -> new Solution.Note("x", 0, null, Solution.PayloadKind.TEXT, ""));
        expectIae(() -> new Solution.Note("x", 0, "\t", Solution.PayloadKind.TEXT, ""));
        expectIae(() -> new Solution.Note("x", 0, "s", null, ""));
        expectIae(() -> new Solution.Note("x", 0, "s", Solution.PayloadKind.TEXT, null));

        Solution.Note concurrent = new Solution.Note("c", 0, "s", Solution.PayloadKind.TEXT, "v");
        eq(1, race(24, concurrent::beginSend));
        eq(1, race(24, concurrent::deliver));
        eq(1, race(24, concurrent::markRead));
        eq(Solution.DeliveryState.DELIVERED, concurrent.state());
        yes(concurrent.isRead());
    }

    private static int race(int count, Callable<Boolean> action) throws Exception {
        CountDownLatch ready = new CountDownLatch(count);
        CountDownLatch start = new CountDownLatch(1);
        AtomicInteger successes = new AtomicInteger();
        AtomicReference<Throwable> failure = new AtomicReference<>();
        List<Thread> threads = new ArrayList<>();
        for (int i = 0; i < count; i++) {
            Thread t = new Thread(() -> {
                ready.countDown();
                try {
                    start.await();
                    if (action.call()) successes.incrementAndGet();
                } catch (Throwable ex) { failure.compareAndSet(null, ex); }
            });
            threads.add(t);
            t.start();
        }
        ready.await();
        start.countDown();
        for (Thread t : threads) t.join();
        if (failure.get() != null) throw new AssertionError(failure.get());
        return successes.get();
    }
    private static void yes(boolean v) { if (!v) throw new AssertionError("expected true"); }
    private static void no(boolean v) { if (v) throw new AssertionError("expected false"); }
    private static void eq(Object expected, Object actual) {
        if (!Objects.equals(expected, actual)) throw new AssertionError("expected=" + expected + " actual=" + actual);
    }
    private static void expectIae(Runnable r) {
        try { r.run(); throw new AssertionError("expected IllegalArgumentException"); }
        catch (IllegalArgumentException expected) { }
    }
}

