        expectIae(() -> new Solution.Announcement(" \u2003 ", "b", 0));
        expectIae(() -> new Solution.Announcement("h", "\t", 0));
        expectIae(() -> new Solution.Announcement("h", "b", -1));

        Solution.AnnouncementHub hub = Solution.newHub();
        StringBuilder log = new StringBuilder();
        EqualListener first = new EqualListener("1", log);
        EqualListener second = new EqualListener("2", log);
        Solution.subscribe(hub, first);
        Solution.subscribe(hub, first);
        Solution.subscribe(hub, second);
        Solution.publish(hub, a);
        eq("12", log.toString());
        yes(Solution.unsubscribe(hub, first));
        no(Solution.unsubscribe(hub, first));
        log.setLength(0);
        Solution.publish(hub, a);
        eq("2", log.toString());

        Solution.AnnouncementHub snapshotHub = Solution.newHub();
        StringBuilder snapshotLog = new StringBuilder();
        Solution.AnnouncementListener b = x -> snapshotLog.append("B");
        Solution.AnnouncementListener c = x -> snapshotLog.append("C");
        Solution.AnnouncementListener removerAdder = x -> {
            snapshotLog.append("A");
            Solution.unsubscribe(snapshotHub, b);
            Solution.subscribe(snapshotHub, c);
        };
        Solution.subscribe(snapshotHub, removerAdder);
        Solution.subscribe(snapshotHub, b);
        Solution.publish(snapshotHub, a);
        eq("AB", snapshotLog.toString());
        snapshotLog.setLength(0);
        Solution.publish(snapshotHub, a);
        eq("AC", snapshotLog.toString());

        Solution.AnnouncementHub failingHub = Solution.newHub();
        RuntimeException boom = new RuntimeException("boom");
        StringBuilder failureLog = new StringBuilder();
        Solution.subscribe(failingHub, x -> failureLog.append("x"));
        Solution.subscribe(failingHub, x -> { failureLog.append("y"); throw boom; });
        Solution.subscribe(failingHub, x -> failureLog.append("z"));
        try {
            Solution.publish(failingHub, a);
            throw new AssertionError("expected callback exception");
        } catch (RuntimeException ex) {
            if (ex != boom) throw new AssertionError("exception identity changed");
        }
        eq("xy", failureLog.toString());

        Solution.AnnouncementHub other = Solution.newHub();
        Solution.publish(other, a);
        no(Solution.unsubscribe(other, second));
        expectIae(() -> Solution.subscribe(null, first));
        expectIae(() -> Solution.subscribe(hub, null));
        expectIae(() -> Solution.unsubscribe(null, first));
        expectIae(() -> Solution.unsubscribe(hub, null));
        expectIae(() -> Solution.publish(null, a));
        expectIae(() -> Solution.publish(hub, null));
    }

    private static final class EqualListener implements Solution.AnnouncementListener {
        private final String value;
        private final StringBuilder log;
        EqualListener(String value, StringBuilder log) { this.value = value; this.log = log; }
        public void onAnnouncement(Solution.Announcement announcement) { log.append(value); }
        public boolean equals(Object other) { return other instanceof EqualListener; }
        public int hashCode() { return 1; }
    }
    private static void yes(boolean v) { if (!v) throw new AssertionError("expected true"); }
    private static void no(boolean v) { if (v) throw new AssertionError("expected false"); }
    private static void eq(Object expected, Object actual) {
        if (!Objects.equals(expected, actual)) throw new AssertionError("expected=" + expected + " actual=" + actual);
    }
    private static void expectIae(Runnable r) {
        try { r.run(); throw new AssertionError("expected IllegalArgumentException"); }
        catch (IllegalArgumentException expected) { }
    }
}

