import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public final class Solution {
    public enum Severity { LOW, MEDIUM, HIGH }

    public static final class Entry {
        private final long id;
        private final String text;
        private final Severity severity;
        private final long logicalTick;

        private Entry(long id, String text, Severity severity, long logicalTick) {
            this.id = id;
            this.text = text;
            this.severity = severity;
            this.logicalTick = logicalTick;
        }

        public long getId() { return id; }
        public String getText() { return text; }
        public Severity getSeverity() { return severity; }
        public long getLogicalTick() { return logicalTick; }
    }

    private static final List<Entry> LEDGER = new ArrayList<>();
    private static long nextId = 1;

    private Solution() {}

    public static synchronized Entry append(String text, Severity severity,
                                            long logicalTick) {
        if (text == null || text.isBlank()
                || severity == null || logicalTick < 0) {
            throw new IllegalArgumentException("invalid entry");
        }
        Entry entry = new Entry(nextId++, text, severity, logicalTick);
        LEDGER.add(entry);
        return entry;
    }

    public static synchronized List<Entry> entries() {
        return Collections.unmodifiableList(new ArrayList<>(LEDGER));
    }

    public static synchronized void clear() {
        LEDGER.clear();
        nextId = 1;
    }
}

