public class SolutionTest {
    public static void main(String[] args) throws Exception {
        Solution.clear();
        eq(0, Solution.entries().size());
        Solution.Entry first = Solution.append("  event  ", Solution.Severity.LOW, 0);
        Solution.Entry second = Solution.append("\u2003event\u2003", Solution.Severity.HIGH, Long.MAX_VALUE);
        eq(1L, first.getId());
        eq("  event  ", first.getText());
        eq(Solution.Severity.LOW, first.getSeverity());
        eq(0L, first.getLogicalTick());
        eq(2L, second.getId());
        eq("\u2003event\u2003", second.getText());
        eq(Long.MAX_VALUE, second.getLogicalTick());

        List<Solution.Entry> snapshot = Solution.entries();
        eq(2, snapshot.size());
        expectUoe(() -> snapshot.add(first));
        Solution.append("third", Solution.Severity.MEDIUM, 3);
        eq(2, snapshot.size());
        eq(3, Solution.entries().size());

        expectIae(() -> Solution.append(null, Solution.Severity.LOW, 0));
        expectIae(() -> Solution.append(" \u2003 ", Solution.Severity.LOW, 0));
        expectIae(() -> Solution.append("x", null, 0));
        expectIae(() -> Solution.append("x", Solution.Severity.LOW, -1));
        Solution.Entry afterRejected = Solution.append("after", Solution.Severity.LOW, 4);
        eq(4L, afterRejected.getId());

        Solution.clear();
        eq(0, Solution.entries().size());
        eq(2, snapshot.size());
        eq(1L, Solution.append("reset", Solution.Severity.MEDIUM, 1).getId());

        Solution.clear();
        final int threads = 8;
        final int each = 40;
        CountDownLatch ready = new CountDownLatch(threads);
        CountDownLatch start = new CountDownLatch(1);
        AtomicReference<Throwable> failure = new AtomicReference<>();
        List<Thread> workers = new ArrayList<>();
        for (int t = 0; t < threads; t++) {
            final int threadNumber = t;
            Thread worker = new Thread(() -> {
                ready.countDown();
                try {
                    start.await();
                    for (int i = 0; i < each; i++)
                        Solution.append("t" + threadNumber + "-" + i, Solution.Severity.LOW, i);
                } catch (Throwable ex) { failure.compareAndSet(null, ex); }
            });
            workers.add(worker);
            worker.start();
        }
        ready.await();
        start.countDown();
        for (Thread worker : workers) worker.join();
