from copy import deepcopy
from collections.abc import Mapping


def find_notices(notices, principal, *, district, locality,
                 department=None, arrangement=None):
    if not isinstance(principal, Mapping) or principal.get("authenticated") is not True:
        raise PermissionError("authentication required")
    if not isinstance(notices, (list, tuple)):
        raise TypeError("notices must be a list or tuple")
    filters = (district, locality, department, arrangement)
    if any(value is not None and not isinstance(value, str) for value in filters):
        raise TypeError("filters must be strings or None")

    required = ("id", "district", "locality", "department", "arrangement", "published")
    selected = []
    for notice in notices:
        if not isinstance(notice, Mapping):
            raise ValueError("each notice must be a mapping")
        if any(key not in notice for key in required):
            raise ValueError("notice is missing a required field")
        if any(not isinstance(notice[key], str) for key in required[:-1]):
            raise ValueError("notice text fields must be strings")
        if not isinstance(notice["published"], bool):
            raise ValueError("published must be boolean")
        if (notice["district"] == district
                and notice["locality"] == locality
                and (department is None or notice["department"] == department)
                and (arrangement is None or notice["arrangement"] == arrangement)
                and notice["published"]):
            selected.append(dict(notice))
    return deepcopy(selected)

