#[path = "solution.rs"]
mod solution;

use solution::{Command, Reply, Workshop};

fn workshop(name: &str) -> Workshop {
    Workshop { name: name.to_string(), ..Workshop::default() }
}

#[test]
fn health_and_empty_summary_are_exact_and_non_mutating() {
    let mut w = workshop("Forge");
    let before = w.clone();
    assert_eq!(solution::dispatch(&mut w, Command::Health), Reply::Text("ready".into()));
    assert_eq!(w, before);
    assert_eq!(solution::dispatch(&mut w, Command::Summary), Reply::Text("Forge|".into()));
    assert_eq!(w, before);
}

#[test]
fn zones_are_trimmed_sorted_and_case_sensitive() {
    let mut w = workshop("shop");
    assert_eq!(solution::dispatch(&mut w, Command::AddZone("  beta  ".into())), Reply::Changed);
    assert_eq!(solution::dispatch(&mut w, Command::AddZone("alpha".into())), Reply::Changed);
    assert_eq!(solution::dispatch(&mut w, Command::AddZone("Beta".into())), Reply::Changed);
    assert_eq!(solution::dispatch(&mut w, Command::Summary), Reply::Text("shop|Beta,alpha,beta".into()));

    let before = w.clone();
    assert_eq!(solution::dispatch(&mut w, Command::AddZone(" beta ".into())), Reply::Conflict);
    assert_eq!(w, before);
    assert_eq!(solution::dispatch(&mut w, Command::Zone(" BETA ".into())), Reply::NotFound);
    assert_eq!(w, before);
}

#[test]
fn malformed_zone_names_and_lookups_are_rejected_atomically() {
    let mut w = workshop("shop");
    assert_eq!(solution::dispatch(&mut w, Command::AddZone(" known ".into())), Reply::Changed);
    assert_eq!(solution::dispatch(&mut w, Command::AddTool {
        id: 4,
        name: "plane".into(),
        zone: "known".into(),
    }), Reply::Changed);
    assert_eq!(solution::dispatch(&mut w, Command::AddTool {
        id: 2,
        name: "file".into(),
        zone: "known".into(),
    }), Reply::Changed);

    for name in ["", "   ", "\t", "\u{2003}"] {
        let before = w.clone();
        assert_eq!(solution::dispatch(&mut w, Command::Zone(name.into())), Reply::Invalid);
        assert_eq!(w, before);
    }

    let before = w.clone();
    assert_eq!(solution::dispatch(&mut w, Command::Zone(" absent ".into())), Reply::NotFound);
    assert_eq!(w, before);
    assert_eq!(solution::dispatch(&mut w, Command::Zone("  known  ".into())), Reply::Text("4,2".into()));

    for name in ["", "   ", "\t\n", "\u{2003}"] {
        let before = w.clone();
        assert_eq!(solution::dispatch(&mut w, Command::AddZone(name.into())), Reply::Invalid);
        assert_eq!(w, before);
    }
}

#[test]
fn tools_preserve_zone_insertion_order_and_trim_stored_names() {
    let mut w = workshop("shop");
    assert_eq!(solution::dispatch(&mut w, Command::AddZone(" bench ".into())), Reply::Changed);
    assert_eq!(solution::dispatch(&mut w, Command::AddTool {
        id: u64::MAX,
        name: "  mallet  ".into(),
        zone: " bench ".into(),
    }), Reply::Changed);
    assert_eq!(solution::dispatch(&mut w, Command::AddTool {
        id: 0,
        name: "saw".into(),
        zone: "bench".into(),
    }), Reply::Changed);

    assert_eq!(solution::dispatch(&mut w, Command::Zone("  bench  ".into())), Reply::Text(format!("{},0", u64::MAX)));
    assert_eq!(solution::dispatch(&mut w, Command::Tool(u64::MAX)), Reply::Text(format!("{}|mallet|bench", u64::MAX)));
    assert_eq!(w.tools.get(&u64::MAX).unwrap().name, "mallet");
    assert_eq!(w.tools.get(&u64::MAX).unwrap().zone, "bench");
}

#[test]
fn missing_zone_and_malformed_tool_names_do_not_mutate() {
    let mut w = workshop("shop");
    solution::dispatch(&mut w, Command::AddZone("known".into()));

    let before = w.clone();
    assert_eq!(solution::dispatch(&mut w, Command::AddTool {
        id: 1,
        name: "hammer".into(),
        zone: "missing".into(),
    }), Reply::NotFound);
    assert_eq!(w, before);

    for (name, zone) in [("", "known"), ("   ", "known"), ("hammer", "  ")] {
        let before = w.clone();
        assert_eq!(solution::dispatch(&mut w, Command::AddTool {
            id: 2,
            name: name.into(),
            zone: zone.into(),
        }), Reply::Invalid);
        assert_eq!(w, before);
    }
}

#[test]
fn duplicate_tool_id_conflicts_without_disturbing_original() {
    let mut w = workshop("shop");
    solution::dispatch(&mut w, Command::AddZone("a".into()));
    solution::dispatch(&mut w, Command::AddZone("b".into()));
    solution::dispatch(&mut w, Command::AddTool { id: 9, name: "first".into(), zone: "a".into() });
    let before = w.clone();

    assert_eq!(solution::dispatch(&mut w, Command::AddTool { id: 9, name: "second".into(), zone: "b".into() }), Reply::Conflict);
    assert_eq!(w, before);
    assert_eq!(solution::dispatch(&mut w, Command::Tool(9)), Reply::Text("9|first|a".into()));
}

#[test]
fn removing_tools_updates_only_their_zone_and_missing_removal_is_atomic() {
    let mut w = workshop("shop");
    solution::dispatch(&mut w, Command::AddZone("a".into()));
    solution::dispatch(&mut w, Command::AddTool { id: 1, name: "one".into(), zone: "a".into() });
    solution::dispatch(&mut w, Command::AddTool { id: 2, name: "two".into(), zone: "a".into() });

    assert_eq!(solution::dispatch(&mut w, Command::RemoveTool(1)), Reply::Changed);
    assert_eq!(solution::dispatch(&mut w, Command::Zone("a".into())), Reply::Text("2".into()));
    assert_eq!(solution::dispatch(&mut w, Command::Tool(1)), Reply::NotFound);

    let before = w.clone();
    assert_eq!(solution::dispatch(&mut w, Command::RemoveTool(1)), Reply::NotFound);
    assert_eq!(w, before);
}

#[test]
fn removing_a_zone_cascades_to_all_assigned_tools() {
    let mut w = workshop("shop");
    solution::dispatch(&mut w, Command::AddZone("keep".into()));
    solution::dispatch(&mut w, Command::AddZone("drop".into()));
    solution::dispatch(&mut w, Command::AddTool { id: 1, name: "one".into(), zone: "drop".into() });
    solution::dispatch(&mut w, Command::AddTool { id: 2, name: "two".into(), zone: "keep".into() });
    solution::dispatch(&mut w, Command::AddTool { id: 3, name: "three".into(), zone: "drop".into() });

    assert_eq!(solution::dispatch(&mut w, Command::RemoveZone("  drop ".into())), Reply::Changed);
    assert_eq!(solution::dispatch(&mut w, Command::Summary), Reply::Text("shop|keep".into()));
    assert_eq!(solution::dispatch(&mut w, Command::Tool(1)), Reply::NotFound);
    assert_eq!(solution::dispatch(&mut w, Command::Tool(3)), Reply::NotFound);
    assert_eq!(solution::dispatch(&mut w, Command::Tool(2)), Reply::Text("2|two|keep".into()));

    let before = w.clone();
    assert_eq!(solution::dispatch(&mut w, Command::RemoveZone("drop".into())), Reply::NotFound);
    assert_eq!(w, before);
}

