#[path = "solution.rs"]
mod solution;

use solution::{RecordFormat, TranscodeError};

fn output(result: Result<String, TranscodeError>) -> String {
    match result {
        Ok(value) => value,
        Err(_) => panic!("expected successful transcode"),
    }
}

fn assert_malformed(result: Result<String, TranscodeError>) {
    match result {
        Err(TranscodeError::Malformed) => {}
        _ => panic!("expected Malformed"),
    }
}

#[test]
fn empty_inputs_have_canonical_outputs() {
    assert_eq!(output(solution::transcode_records("", RecordFormat::Lines, RecordFormat::Lines, false)), "");
    assert_eq!(output(solution::transcode_records("", RecordFormat::Lines, RecordFormat::Bracketed, true)), "[]");
    assert_eq!(output(solution::transcode_records("", RecordFormat::Lines, RecordFormat::Bracketed, false)), "[ ]");
    assert_eq!(output(solution::transcode_records(" [ ] \n", RecordFormat::Bracketed, RecordFormat::Lines, true)), "");
    assert_eq!(output(solution::transcode_records("[]", RecordFormat::Bracketed, RecordFormat::Bracketed, false)), "[ ]");
}

#[test]
fn lines_are_sorted_and_encoding_is_canonicalized() {
    let input = "z=%7e%2f%F0%9f%98%80\na=%41Zaz09-_.~\n";
    let expected = "a=AZaz09-_.~\nz=~%2F%F0%9F%98%80\n";
    assert_eq!(output(solution::transcode_records(input, RecordFormat::Lines, RecordFormat::Lines, true)), expected);
    assert_eq!(input, "z=%7e%2f%F0%9f%98%80\na=%41Zaz09-_.~\n");
}

#[test]
fn bracketed_ascii_whitespace_is_accepted_around_records_and_container() {
    let input = " \t\n\r\u{000c}[\t\n\r\u{000c} b=%78 \t\n\r\u{000c},\t\n\r\u{000c} a=one%20two \t\n\r\u{000c}]\t\n\r\u{000c} ";
    assert_eq!(output(solution::transcode_records(input, RecordFormat::Bracketed, RecordFormat::Lines, false)), "a=one%20two\nb=x\n");

    for invalid in ["[a=x y]", "[a =x]", "[a= x]", "[a\t=x]"] {
        assert_malformed(solution::transcode_records(invalid, RecordFormat::Bracketed, RecordFormat::Lines, false));
    }
}

#[test]
fn compact_and_spaced_bracketed_forms_are_exact() {
    let input = "b=two\na=one";
    assert_eq!(output(solution::transcode_records(input, RecordFormat::Lines, RecordFormat::Bracketed, true)), "[a=one,b=two]");
    assert_eq!(output(solution::transcode_records(input, RecordFormat::Lines, RecordFormat::Bracketed, false)), "[ a=one, b=two ]");
}

#[test]
fn keys_are_validated_and_remain_case_sensitive() {
    for input in ["=x", "a-b=x", "a.b=x", "a b=x", "%61=x", "é=x"] {
        assert_malformed(solution::transcode_records(input, RecordFormat::Lines, RecordFormat::Lines, false));
    }

    assert_eq!(output(solution::transcode_records("a=lower\nA=upper\na_1=number", RecordFormat::Lines, RecordFormat::Lines, false)), "A=upper\na=lower\na_1=number\n");
}

#[test]
fn malformed_lines_records_are_rejected() {
    for input in ["\n", "a=x\n\n", "a=x\r\n", "a=x\rb=y", "a", "a=x=y"] {
        assert_malformed(solution::transcode_records(input, RecordFormat::Lines, RecordFormat::Bracketed, true));
    }
}

#[test]
fn malformed_bracket_structure_and_blank_records_are_rejected() {
    for input in ["a=x", "[", "]", "[a=x", "a=x]", "[,a=x]", "[a=x,]", "[a=x,,b=y]", "[ , ]"] {
        assert_malformed(solution::transcode_records(input, RecordFormat::Bracketed, RecordFormat::Lines, false));
    }
}

#[test]
fn raw_disallowed_value_bytes_and_bad_percent_escapes_are_malformed() {
    for input in ["a=/", "a= ", "a=é", "a=%", "a=%0", "a=%GG", "a=%0g"] {
        assert_malformed(solution::transcode_records(input, RecordFormat::Lines, RecordFormat::Lines, false));
    }

    assert_eq!(output(solution::transcode_records("a=%0d%00", RecordFormat::Lines, RecordFormat::Lines, false)), "a=%0D%00\n");
}

#[test]
fn decoded_values_must_be_utf8() {
    match solution::transcode_records("a=%FF", RecordFormat::Lines, RecordFormat::Lines, false) {
        Err(TranscodeError::InvalidUtf8) => {}
        _ => panic!("expected InvalidUtf8"),
    }
    match solution::transcode_records("[a=%C3%28]", RecordFormat::Bracketed, RecordFormat::Lines, false) {
        Err(TranscodeError::InvalidUtf8) => {}
        _ => panic!("expected InvalidUtf8"),
    }
    assert_eq!(output(solution::transcode_records("a=%C3%A9", RecordFormat::Lines, RecordFormat::Lines, false)), "a=%C3%A9\n");
}

#[test]
fn duplicate_keys_are_errors_but_case_variants_are_distinct() {
    match solution::transcode_records("b=x\na=one\na=two", RecordFormat::Lines, RecordFormat::Bracketed, true) {
        Err(TranscodeError::DuplicateKey) => {}
        _ => panic!("expected DuplicateKey"),
    }
    match solution::transcode_records("[ a=one, b=x, a=two ]", RecordFormat::Bracketed, RecordFormat::Lines, false) {
        Err(TranscodeError::DuplicateKey) => {}
        _ => panic!("expected DuplicateKey"),
    }
    assert_eq!(output(solution::transcode_records("a=x\nA=y", RecordFormat::Lines, RecordFormat::Lines, false)), "A=y\na=x\n");
}

#[test]
fn repeated_transcoding_is_stable_and_does_not_change_the_input() {
    let input = String::from("[ z=%2f, a=%7E ]");
    let first = output(solution::transcode_records(&input, RecordFormat::Bracketed, RecordFormat::Bracketed, false));
    let second = output(solution::transcode_records(&input, RecordFormat::Bracketed, RecordFormat::Bracketed, false));
    assert_eq!(first, "[ a=~, z=%2F ]");
    assert_eq!(second, first);
    assert_eq!(input, "[ z=%2f, a=%7E ]");
}

