import java.util.*;

public class SolutionTest {
    public static void main(String[] args) {
        int[][] spots = {{3, 4, 1}, {4, 4, 0}, {-3, -4, 1}, {6, 0, 1}};
        int[][] result = Solution.visibleMarkers(spots, 0, 0, 5, 0x123456, false, 0);
        matrix(new int[][]{{3, 4, 0x123456}, {-3, -4, 0x123456}}, result);
        matrix(new int[][]{{3, 4, 1}, {4, 4, 0}, {-3, -4, 1}, {6, 0, 1}}, spots);
        spots[0][0] = 99;
        eq(3, result[0][0]);
        result[0][0] = 88;
        eq(-3, result[1][0]);

        matrix(new int[0][0], Solution.visibleMarkers(new int[0][], 0, 0, 0, 0, false, 0));
        matrix(new int[][]{{1, 2, 0xFF00FF}},
                Solution.visibleMarkers(new int[][]{{1, 2, 1}}, 1, 2, 0, 0, true, -1));
        matrix(new int[][]{{1, 2, 0xFFFF00}},
                Solution.visibleMarkers(new int[][]{{1, 2, 1}}, 1, 2, 0, 0, true, 7));

        int[][] exactBoundary = {
                {Integer.MAX_VALUE, 1, 1},
                {Integer.MAX_VALUE, 0, 1}
        };
        matrix(new int[][]{{Integer.MAX_VALUE, 0, 0xABCDEF}},
                Solution.visibleMarkers(exactBoundary, 0, 0, Integer.MAX_VALUE,
                        0xABCDEF, false, 0));

        int[][] extremes = {
                {Integer.MAX_VALUE, Integer.MAX_VALUE, 1},
                {Integer.MIN_VALUE, Integer.MIN_VALUE, 1}
        };
        matrix(new int[][]{
                        {Integer.MAX_VALUE, Integer.MAX_VALUE, 0},
                        {Integer.MIN_VALUE, Integer.MIN_VALUE, 0}
                },
                Solution.visibleMarkers(extremes, Integer.MIN_VALUE, Integer.MAX_VALUE,
                        Long.MAX_VALUE, 0, false, 0));
        matrix(new int[][]{{Integer.MAX_VALUE, 0, 7}},
                Solution.visibleMarkers(new int[][]{{Integer.MAX_VALUE, 0, 1}},
                        Integer.MIN_VALUE, 0, 4294967295L, 7, false, 0));

        expectIae(() -> Solution.visibleMarkers(null, 0, 0, 0, 0, false, 0));
        expectIae(() -> Solution.visibleMarkers(new int[][]{null}, 0, 0, 0, 0, false, 0));
        expectIae(() -> Solution.visibleMarkers(new int[][]{{1, 2}}, 0, 0, 0, 0, false, 0));
        expectIae(() -> Solution.visibleMarkers(new int[][]{{1, 2, 1, 4}}, 0, 0, 0, 0, false, 0));
        expectIae(() -> Solution.visibleMarkers(new int[][]{{1, 2, 2}}, 0, 0, 0, 0, false, 0));
        expectIae(() -> Solution.visibleMarkers(new int[][]{{1, 2, -1}}, 0, 0, 0, 0, false, 0));
        expectIae(() -> Solution.visibleMarkers(new int[0][], 0, 0, -1, 0, false, 0));
        expectIae(() -> Solution.visibleMarkers(new int[0][], 0, 0, 0, -1, false, 0));
        expectIae(() -> Solution.visibleMarkers(new int[0][], 0, 0, 0, 0x1000000, true, 0));
    }

    private static void matrix(int[][] expected, int[][] actual) {
        if (!Arrays.deepEquals(expected, actual)) {
            throw new AssertionError("arrays differ");
        }
    }

    private static void eq(int expected, int actual) {
        if (expected != actual) {
            throw new AssertionError("expected=" + expected + " actual=" + actual);
        }
    }

    private static void expectIae(Runnable action) {
        try {
            action.run();
            throw new AssertionError("expected IllegalArgumentException");
        } catch (IllegalArgumentException expected) {
        }
    }
}

