import java.util.*;

public class SolutionTest {
    public static void main(String[] args) {
        Solution.Asset a = new Solution.Asset(1, "g1", " first ");
        Solution.Asset b = new Solution.Asset(Long.MAX_VALUE, "g2", "second");
        Solution.Asset c = new Solution.Asset(1, "g1", "duplicate id");
        eq(1L, a.getId());
        eq("g1", a.getGroup());
        eq(" first ", a.getName());

        List<Solution.Asset> assets = new LinkedList<>(Arrays.asList(a, b, c));
        Set<String> groups = new LinkedHashSet<>(Collections.singletonList("g1"));
        List<Solution.Asset> selected = Solution.selectAssets(assets, groups);
        eq(2, selected.size());
        same(a, selected.get(0));
        same(c, selected.get(1));
        selected.clear();
        eq(3, assets.size());
        eq(1, groups.size());

        List<Solution.Asset> all = Solution.selectAssets(assets, Set.of());
        eq(3, all.size());
        same(a, all.get(0));
        same(b, all.get(1));
        same(c, all.get(2));
        all.add(a);
        eq(4, all.size());
        eq(3, assets.size());

        List<Solution.Asset> singletonAll = Solution.selectAssets(
                Collections.singletonList(b), Set.of());
        eq(1, singletonAll.size());
        same(b, singletonAll.get(0));
        singletonAll.clear();

        List<Solution.Asset> noAssets = Solution.selectAssets(
                Collections.emptyList(), Set.of());
        eq(0, noAssets.size());
        noAssets.add(a);
        eq(1, noAssets.size());

        List<Solution.Asset> immutableGroupMatch = Solution.selectAssets(
                assets, Set.of("g2"));
        eq(1, immutableGroupMatch.size());
        same(b, immutableGroupMatch.get(0));

        Set<String> sortedGroups = new TreeSet<>(Arrays.asList("g1", "unused"));
        List<Solution.Asset> treeSelected = Solution.selectAssets(assets, sortedGroups);
        eq(2, treeSelected.size());
        same(a, treeSelected.get(0));
        same(c, treeSelected.get(1));

        eq(0, Solution.selectAssets(assets, Collections.singleton("G1")).size());
        same(a, Solution.findAsset(assets, 1));
        same(b, Solution.findAsset(assets, Long.MAX_VALUE));
        eq(null, Solution.findAsset(assets, 99));

        Solution.Asset whitespace = new Solution.Asset(2, " ", "\t");
        eq(" ", whitespace.getGroup());
        eq("\t", whitespace.getName());
        expectIae(() -> new Solution.Asset(0, "g", "n"));
        expectIae(() -> new Solution.Asset(-1, "g", "n"));
        expectIae(() -> new Solution.Asset(1, null, "n"));
        expectIae(() -> new Solution.Asset(1, "", "n"));
        expectIae(() -> new Solution.Asset(1, "g", null));
        expectIae(() -> new Solution.Asset(1, "g", ""));

        expectIae(() -> Solution.selectAssets(null, Collections.emptySet()));
        expectIae(() -> Solution.selectAssets(assets, null));
        expectIae(() -> Solution.selectAssets(Arrays.asList(a, null), Collections.emptySet()));
        Set<String> badGroups = new HashSet<>();
        badGroups.add(null);
        expectIae(() -> Solution.selectAssets(Collections.emptyList(), badGroups));

        expectIae(() -> Solution.findAsset(null, 1));
        expectIae(() -> Solution.findAsset(Arrays.asList(a, null), 1));
        expectIae(() -> Solution.findAsset(Arrays.asList(a, null), 2));
        expectIae(() -> Solution.findAsset(assets, 0));
        expectIae(() -> Solution.findAsset(assets, -1));
    }

    private static void same(Object expected, Object actual) {
        if (expected != actual) {
            throw new AssertionError("objects differ");
        }
    }

    private static void eq(Object expected, Object actual) {
        if (!Objects.equals(expected, actual)) {
            throw new AssertionError("expected=" + expected + " actual=" + actual);
        }
    }

    private static void expectIae(Runnable action) {
        try {
            action.run();
            throw new AssertionError("expected IllegalArgumentException");
        } catch (IllegalArgumentException expected) {
        }
    }
}

