import java.util.*;

public class SolutionTest {
    public static void main(String[] args) {
        Map<Integer, Collection<Integer>> initial = new HashMap<>();
        initial.put(9, new ArrayList<>(Arrays.asList(5, 3, 5)));
        initial.put(2, new LinkedHashSet<>(Arrays.asList(8, 1)));
        List<Integer> createPermissions = new ArrayList<>(Arrays.asList(7, 2, 7));
        List<Solution.Change> changes = new ArrayList<>();
        changes.add(new Solution.Change(Solution.Kind.CREATE, 4, createPermissions));
        changes.add(new Solution.Change(Solution.Kind.REPLACE, 9, Arrays.asList(6, 4)));
        changes.add(new Solution.Change(Solution.Kind.DELETE, 2, null));

        Map<Integer, Set<Integer>> result = Solution.apply(initial, changes);
        eq(Arrays.asList(4, 9), new ArrayList<>(result.keySet()));
        eq(Arrays.asList(2, 7), new ArrayList<>(result.get(4)));
        eq(Arrays.asList(4, 6), new ArrayList<>(result.get(9)));
        eq(Arrays.asList(2, 9), sorted(initial.keySet()));
        eq(Arrays.asList(1, 8), sorted(initial.get(2)));
        eq(Arrays.asList(3, 5, 5), sorted(initial.get(9)));

        expectUoe(() -> result.put(10, Collections.emptySet()));
        expectUoe(() -> result.get(4).add(99));
        createPermissions.add(99);
        initial.get(9).add(100);
        changes.clear();
        eq(Arrays.asList(2, 7), new ArrayList<>(result.get(4)));
        eq(Arrays.asList(4, 6), new ArrayList<>(result.get(9)));

        Map<Integer, Set<Integer>> empty = Solution.apply(
                Collections.emptyMap(), Collections.emptyList());
        eq(0, empty.size());
        expectUoe(() -> empty.put(1, Collections.emptySet()));

        Map<Integer, Collection<Integer>> atomicInitial = new HashMap<>();
        atomicInitial.put(1, new ArrayList<>(Collections.singletonList(10)));
        List<Solution.Change> badTransaction = Arrays.asList(
                new Solution.Change(Solution.Kind.CREATE, 2, Collections.singletonList(20)),
                new Solution.Change(Solution.Kind.CREATE, 1, Collections.singletonList(30)));
        expectIae(() -> Solution.apply(atomicInitial, badTransaction));
        eq(Collections.singletonList(1), new ArrayList<>(atomicInitial.keySet()));
        eq(Collections.singletonList(10), new ArrayList<>(atomicInitial.get(1)));

        Map<Integer, Collection<Integer>> deleteBase = new HashMap<>();
        deleteBase.put(1, new ArrayList<>(Arrays.asList(3, 2)));
        eq(0, Solution.apply(deleteBase, Collections.singletonList(
                new Solution.Change(Solution.Kind.DELETE, 1, null))).size());
        eq(0, Solution.apply(deleteBase, Collections.singletonList(
                new Solution.Change(Solution.Kind.DELETE, 1, Collections.emptyList()))).size());
        eq(0, Solution.apply(deleteBase, Collections.singletonList(
                new Solution.Change(Solution.Kind.DELETE, 1, Arrays.asList(5, 6)))).size());
        eq(Arrays.asList(2, 3), sorted(deleteBase.get(1)));

        expectIae(() -> {
            Solution.Change change = new Solution.Change(
                    Solution.Kind.DELETE, 1, Collections.singletonList(0));
            Solution.apply(deleteBase, Collections.singletonList(change));
        });
        eq(Arrays.asList(2, 3), sorted(deleteBase.get(1)));
        expectIae(() -> {
            Solution.Change change = new Solution.Change(
                    Solution.Kind.DELETE, 1, Collections.singletonList(-1));
            Solution.apply(deleteBase, Collections.singletonList(change));
        });
        eq(Arrays.asList(2, 3), sorted(deleteBase.get(1)));
        expectIae(() -> {
            Solution.Change change = new Solution.Change(
                    Solution.Kind.DELETE, 1, Arrays.asList(2, null));
            Solution.apply(deleteBase, Collections.singletonList(change));
        });
        eq(Arrays.asList(2, 3), sorted(deleteBase.get(1)));

        expectIae(() -> new Solution.Change(null, 1, Collections.emptyList()));
        expectIae(() -> new Solution.Change(Solution.Kind.CREATE, 0, Collections.emptyList()));
        expectIae(() -> new Solution.Change(Solution.Kind.CREATE, 1, null));
        expectIae(() -> {
            Solution.Change change = new Solution.Change(
                    Solution.Kind.REPLACE, 1, Arrays.asList(1, null));
            Solution.apply(deleteBase, Collections.singletonList(change));
        });
        eq(Arrays.asList(2, 3), sorted(deleteBase.get(1)));

        expectIae(() -> Solution.apply(null, Collections.emptyList()));
        expectIae(() -> Solution.apply(Collections.emptyMap(), null));
        Map<Integer, Collection<Integer>> nullValue = new HashMap<>();
        nullValue.put(1, null);
        expectIae(() -> Solution.apply(nullValue, Collections.emptyList()));
        Map<Integer, Collection<Integer>> nullKey = new HashMap<>();
        nullKey.put(null, Collections.emptyList());
        expectIae(() -> Solution.apply(nullKey, Collections.emptyList()));
        Map<Integer, Collection<Integer>> badId = new HashMap<>();
        badId.put(0, Collections.emptyList());
        expectIae(() -> Solution.apply(badId, Collections.emptyList()));
        Map<Integer, Collection<Integer>> badPermission = new HashMap<>();
        badPermission.put(1, Arrays.asList(2, -1));
        expectIae(() -> Solution.apply(badPermission, Collections.emptyList()));
        expectIae(() -> Solution.apply(Collections.emptyMap(), Collections.singletonList(null)));
        expectIae(() -> Solution.apply(Collections.emptyMap(), Collections.singletonList(
                new Solution.Change(Solution.Kind.REPLACE, 1, Collections.emptyList()))));
        expectIae(() -> Solution.apply(Collections.emptyMap(), Collections.singletonList(
                new Solution.Change(Solution.Kind.DELETE, 1, null))));
    }

    private static List<Integer> sorted(Collection<Integer> values) {
        List<Integer> copy = new ArrayList<>(values);
        Collections.sort(copy);
        return copy;
    }

    private static void eq(Object expected, Object actual) {
        if (!Objects.equals(expected, actual)) {
            throw new AssertionError("expected=" + expected + " actual=" + actual);
        }
    }

    private static void expectIae(Runnable action) {
        try {
            action.run();
            throw new AssertionError("expected IllegalArgumentException");
        } catch (IllegalArgumentException expected) {
        }
    }

    private static void expectUoe(Runnable action) {
        try {
            action.run();
            throw new AssertionError("expected UnsupportedOperationException");
        } catch (UnsupportedOperationException expected) {
        }
    }
}

