import java.util.*;

public class SolutionTest {
    public static void main(String[] args) {
        List<Solution.Clip> empty = Solution.decodeFeed("");
        eq(0, empty.size());
        expectUoe(() -> empty.add(new Solution.Clip("x", "y")));

        List<Solution.Clip> clips = Solution.decodeFeed(
                "Title|opaque-value\nTitle|opaque-value\nOther|://not-a-scheme\n");
        eq(3, clips.size());
        eq("Title", clips.get(0).title());
        eq("opaque-value", clips.get(0).url());
        eq(clips.get(0), clips.get(1));
        eq("Other", clips.get(2).title());
        eq("://not-a-scheme", clips.get(2).url());
        expectUoe(() -> clips.remove(0));
        eq(3, clips.size());

        List<Solution.Clip> opaque = Solution.decodeFeed("A|%2Fpath%3Fx%3D1");
        eq(1, opaque.size());
        eq("A", opaque.get(0).title());
        eq("%2Fpath%3Fx%3D1", opaque.get(0).url());

        expectIae(() -> Solution.decodeFeed(null));
        expectIae(() -> Solution.decodeFeed("title"));
        expectIae(() -> Solution.decodeFeed("title|url|extra"));
        expectIae(() -> Solution.decodeFeed("|url"));
        expectIae(() -> Solution.decodeFeed("title|"));
        expectIae(() -> Solution.decodeFeed(" |url"));
        expectIae(() -> Solution.decodeFeed("title| \t"));
        expectIae(() -> Solution.decodeFeed(" title|url"));
        expectIae(() -> Solution.decodeFeed("title |url"));
        expectIae(() -> Solution.decodeFeed("title|url "));
        expectIae(() -> Solution.decodeFeed("\u2003title|url"));
        expectIae(() -> Solution.decodeFeed("title|url\u2003"));
        expectIae(() -> Solution.decodeFeed("title|url\r"));
        expectIae(() -> Solution.decodeFeed("title\r|url"));
        expectIae(() -> Solution.decodeFeed("a|b\n\nc|d"));
        expectIae(() -> Solution.decodeFeed("a|b\n\n"));
        expectIae(() -> Solution.decodeFeed("\n\n"));
    }

    private static void eq(Object expected, Object actual) {
        if (!Objects.equals(expected, actual)) {
            throw new AssertionError("expected=" + expected + " actual=" + actual);
        }
    }

    private static void expectIae(Runnable action) {
        try {
            action.run();
            throw new AssertionError("expected IllegalArgumentException");
        } catch (IllegalArgumentException expected) {
        }
    }

    private static void expectUoe(Runnable action) {
        try {
            action.run();
            throw new AssertionError("expected UnsupportedOperationException");
        } catch (UnsupportedOperationException expected) {
        }
    }
}

